  "図書館について、正しいものはどれですか。": "[図書館|としょかん]について、[正|ただ]しいものはどれですか。",
  "二階の部屋で飲み物を飲んでもいいです": "[二|に][階|かい]の[部屋|へや]で[飲み物|のみもの]を[飲|の]んでもいいです",
  "使うとき、お金がいります": "[使|つか]うとき、お[金|かね]がいります",
  "駅から歩いて十分です": "[駅|えき]から[歩|ある]いて[十分|じゅうぶん]です",
  "本は一か月で返します": "[本|ほん]は[一か月|いっかげつ]で[返|かえ]します",
  "日曜日の午後、母が冷蔵庫にケーキを入れました。でも、夜、ケーキはありませんでした。午後、家には父と兄と妹がいました。": "[日曜日|にちようび]の[午後|ごご]、[母|はは]が[冷蔵庫|れいぞうこ]にケーキを[入|い]れました。でも、[夜|よる]、ケーキはありませんでした。[午後|ごご]、[家|いえ]には[父|ちち]と[兄|あに]と[妹|いもうと]がいました。",
  "母は三人に聞きました。父は「私は午後ずっと外で車を洗っていました」と言いました。兄は「私は部屋で勉強していました。甘いものはきらいです」と言いました。妹は「私は知りません」と言いました。": "[母|はは]は[三人|さんにん]に[聞|き]きました。[父|ちち]は「[私|わたし]は[午後|ごご]ずっと[外|そと]で[車|くるま]を[洗|あら]っていました」と[言|い]いました。[兄|あに]は「[私|わたし]は[部屋|へや]で[勉強|べんきょう]していました。[甘|あま]いものはきらいです」と[言|い]いました。[妹|いもうと]は「[私|わたし]は[知|し]りません」と[言|い]いました。",
  "私は小さい探偵です。妹の顔をよく見ました。妹の口の近くに、白いクリームが少しありました。私はすぐわかりました。": "[私|わたし]は[小|ちい]さい[探偵|たんてい]です。[妹|いもうと]の[顔|かお]をよく[見|み]ました。[妹|いもうと]の[口|くち]の[近|ちか]くに、[白|しろ]いクリームが[少|すこ]しありました。[私|わたし]はすぐわかりました。",
  "兄は午後、何をしていましたか。": "[兄|あに]は[午後|ごご]、[何|なに]をしていましたか。",
  "部屋で勉強していました": "[部屋|へや]で[勉強|べんきょう]していました",
  "外で車を洗っていました": "[外|そと]で[車|くるま]を[洗|あら]っていました",
  "ケーキを作っていました": "ケーキを[作|つく]っていました",
  "公園で遊んでいました": "[公園|こうえん]で[遊|あそ]んでいました",
  "ケーキを食べたのはだれですか。": "ケーキを[食|た]べたのはだれですか。",
