  "だれの傘": "だれの[傘|かさ]",
  "雨の日、教室に青い傘が一本ありました。名前はありませんでした。先生は「これはだれの傘ですか」と聞きました。": "[雨|あめ]の[日|ひ]、[教室|きょうしつ]に[青|あお]い[傘|かさ]が[一本|いっぽん]ありました。[名前|なまえ]はありませんでした。[先生|せんせい]は「これはだれの[傘|かさ]ですか」と[聞|き]きました。",
  "三人が「私のです」と言いました。田中さんは「私の傘は青くて、長いです」と言いました。山田さんは「私の傘は青くて、新しいです」と言いました。鈴木さんは「私の傘は青くて、中に黄色い花の絵があります」と言いました。": "[三人|さんにん]が「[私|わたし]のです」と[言|い]いました。[田中|たなか]さんは「[私|わたし]の[傘|かさ]は[青|あお]くて、[長|なが]いです」と[言|い]いました。[山田|やまだ]さんは「[私|わたし]の[傘|かさ]は[青|あお]くて、[新|あたら]しいです」と[言|い]いました。[鈴木|すずき]さんは「[私|わたし]の[傘|かさ]は[青|あお]くて、[中|なか]に[黄色|きいろ]い[花|はな]の[絵|え]があります」と[言|い]いました。",
  "先生は傘を開きました。中に小さい黄色い花の絵がありました。それに、この傘は古くて、短い傘でした。": "[先生|せんせい]は[傘|かさ]を[開|ひら]きました。[中|なか]に[小|ちい]さい[黄色|きいろ]い[花|はな]の[絵|え]がありました。それに、この[傘|かさ]は[古|ふる]くて、[短|みじか]い[傘|かさ]でした。",
  "先生が傘を開くと、中に何がありましたか。": "[先生|せんせい]が[傘|かさ]を[開|ひら]くと、[中|なか]に[何|なに]がありましたか。",
