  "雪の日の手紙": "[雪|ゆき]の[日|ひ]の[手紙|てがみ]",
  "朝、雪がたくさん降りました。山田さんの家のドアの前に、手紙が一つありました。ひらがなで「おたんじょうび おめでとう」と書いてありました。でも、名前はありませんでした。": "[朝|あさ]、[雪|ゆき]がたくさん[降|お]りました。[山田|やまだ]さんの[家|いえ]のドアの[前|まえ]に、[手紙|てがみ]が[一|ひと]つありました。ひらがなで「おたんじょうび おめでとう」と[書|か]いてありました。でも、[名前|なまえ]はありませんでした。",
  "雪の上に、小さい足あとがありました。足あとは、となりの家から来ていました。": "[雪|ゆき]の[上|うえ]に、[小|ちい]さい[足|あし]あとがありました。[足|あし]あとは、となりの[家|いえ]から[来|き]ていました。",
  "となりの家には、三人がいます。背が高いおじいさんと、お母さんと、六歳の男の子です。男の子はよく山田さんと遊びます。": "となりの[家|いえ]には、[三人|さんにん]がいます。[背|せ]が[高|たか]いおじいさんと、お[母|かあ]さんと、[六|ろく][歳|さい]の[男の子|おとこのこ]です。[男の子|おとこのこ]はよく[山田|やまだ]さんと[遊|あそ]びます。",
  "山田さんは「わかりました」と言って、ほほえみました。そして、となりの家へ行きました。": "[山田|やまだ]さんは「わかりました」と[言|い]って、ほほえみました。そして、となりの[家|いえ]へ[行|い]きました。",
  "足あとは、どこから来ていましたか。": "[足|あし]あとは、どこから[来|き]ていましたか。",
