  "あしたは 雨ですから、（　）を 持って いきます。": "あしたは [雨|あめ]ですから、（　）を [持|も]って いきます。",
  "この りんごは 一つ 50円です。とても（　）です。": "この りんごは [一|ひと]つ 50[円|えん]です。とても（　）です。",
  "わたしは 毎日 電車（　）学校へ 行きます。": "わたしは [毎日|まいにち] [電車|でんしゃ]（　）[学校|がっこう]へ [行|い]きます。",
  "つくえの 上（　）本が あります。": "つくえの [上|うえ]（　）[本|ほん]が あります。",
