  "わたしは まいあさ 七時に おきます。あさごはんは パンと たまごです。八時に いえを でて、でんしゃで がっこうへ いきます。がっこうは 九時から 三時までです。": "わたしは まいあさ [七時|しちじ]に おきます。あさごはんは パンと たまごです。[八時|はちじ]に いえを でて、でんしゃで がっこうへ いきます。がっこうは [九時|くじ]から [三時|さんじ]までです。",
