  "田中さんへ\nきょうの かいぎは 四時から 五時に かわりました。ばしょは 三かいの へやです。\n山田": "[田中|たなか]さんへ\nきょうの かいぎは [四時|よじ]から [五時|ごじ]に かわりました。ばしょは [三|さん]かいの へやです。\n[山田|やまだ]",
