  "一かいの へや": "[一|いち]かいの へや",
  "この 人は こうえんで 何を しましたか。": "この [人|ひと]は こうえんで [何|なに]を しましたか。",
  "きのうは 日よう日でした。わたしは ともだちと こうえんへ いきました。こうえんで しゃしんを たくさん とりました。それから、レストランで ひるごはんを たべました。とても おいしかったです。": "きのうは [日|にち]よう[日|ひ]でした。わたしは ともだちと こうえんへ いきました。こうえんで しゃしんを たくさん とりました。それから、レストランで ひるごはんを たべました。とても おいしかったです。",
  "わたしの へやには つくえと いすと ベッドが あります。つくえの 上に パソコンが あります。ねこは いつも ベッドの 上で ねて います。": "わたしの へやには つくえと いすと ベッドが あります。つくえの [上|うえ]に パソコンが あります。ねこは いつも ベッドの [上|うえ]で ねて います。",
  "ベッドの 上": "ベッドの [上|うえ]",
