  "としょかんの おしらせ\n月よう日は やすみです。火よう日から 金よう日は 九時から 七時まで、土よう日と 日よう日は 九時から 五時までです。": "としょかんの おしらせ\n[月|つき]よう[日|び]は やすみです。[火|ひ]よう[日|び]から [金|きん]よう[日|び]は [九時|くじ]から [七時|しちじ]まで、[土|ど]よう[日|び]と [日|にち]よう[日|び]は [九時|くじ]から [五時|ごじ]までです。",
