  "佐藤さんの傘を持って行ったのはだれだと考えられますか。": "[佐藤|さとう]さんの[傘|かさ]を[持|も]って[行|い]ったのはだれだと[考|かんが]えられますか。",
  "山田先生": "[山田|やまだ][先生|せんせい]",
  "割れた窓ガラス": "[割|わ]れた[窓|まど]ガラス",
  "土曜日の朝、小林さんの家の窓ガラスが割れていました。部屋の中には、野球のボールが一つ落ちていました。前の日の夜はひどい雨でしたが、夜中の十二時ごろにやんだそうです。小林さんは、近くに住む探偵の青木さんに相談しました。": "[土曜日|どようび]の[朝|あさ]、[小林|こばやし]さんの[家|いえ]の[窓|まど]ガラスが[割|わ]れていました。[部屋|へや]の[中|なか]には、[野球|やきゅう]のボールが[一|ひと]つ[落|お]ちていました。[前|まえ]の[日|ひ]の[夜|よる]はひどい[雨|あめ]でしたが、[夜中|やちゅう]の[十二時|じゅうにじ]ごろにやんだそうです。[小林|こばやし]さんは、[近|ちか]くに[住|す]む[探偵|たんてい]の[青木|あおき]さんに[相談|そうだん]しました。",
  "青木さんは、近所の子ども三人に話を聞きました。ゆうたは「金曜日の夜、この前の道でキャッチボールをしていたけど、雨が降ってきたので、すぐ帰りました」と言いました。まさきは「土曜日の朝は、家族と車で山へ出かけていました」と言いました。けんじは「土曜日の朝は、ずっと家で寝ていました」と言いました。": "[青木|あおき]さんは、[近所|きんじょ]の[子|こ]ども[三人|さんにん]に[話|はなし]を[聞|き]きました。ゆうたは「[金曜日|きんようび]の[夜|よる]、この[前|まえ]の[道|みち]でキャッチボールをしていたけど、[雨|あめ]が[降|ふ]ってきたので、すぐ[帰|かえ]りました」と[言|い]いました。まさきは「[土曜日|どようび]の[朝|あさ]は、[家族|かぞく]と[車|くるま]で[山|やま]へ[出|で]かけていました」と[言|い]いました。けんじは「[土曜日|どようび]の[朝|あさ]は、ずっと[家|いえ]で[寝|ね]ていました」と[言|い]いました。",
  "青木さんはボールを手に取りました。ボールは少しもぬれていませんでした。それから窓の下を見ると、雨でやわらかくなった土の上に、くつのあとが残っていました。最後に、青木さんは三人のくつを見せてもらいました。けんじのくつにだけ、まだ新しい土が付いていました。": "[青木|あおき]さんはボールを[手|て]に[取|と]りました。ボールは[少|すこ]しもぬれていませんでした。それから[窓|まど]の[下|した]を[見|み]ると、[雨|あめ]でやわらかくなった[土|ど]の[上|うえ]に、くつのあとが[残|のこ]っていました。[最後|さいご]に、[青木|あおき]さんは[三人|さんにん]のくつを[見|み]せてもらいました。けんじのくつにだけ、まだ[新|あたら]しい[土|ど]が[付|つ]いていました。",
  "青木さんは「窓が割れたのは、雨がやんだあとですね。犯人はもうわかりました」と言いました。": "[青木|あおき]さんは「[窓|まど]が[割|わ]れたのは、[雨|あめ]がやんだあとですね。[犯人|はんにん]はもうわかりました」と[言|い]いました。",
