  "山田さん\n来週の金曜日の旅行のことですが、雨が降ったら、旅行はやめて、映画を見に行きませんか。天気がよかったら、予定どおり九時に駅で会いましょう。\nリン": "[山田|やまだ]さん\n[来週|らいしゅう]の[金曜日|きんようび]の[旅行|りょこう]のことですが、[雨|あめ]が[降|ふ]ったら、[旅行|りょこう]はやめて、[映画|えいが]を[見|み]に[行|い]きませんか。[天気|てんき]がよかったら、[予定|よてい]どおり[九時|くじ]に[駅|えき]で[会|あ]いましょう。\nリン",
