  "わたしは先月から料理教室に通っています。最初は簡単な料理しか作れませんでしたが、今は魚の料理も作れるようになりました。来月は友達を家に呼んで、習った料理を作ってあげるつもりです。": "わたしは[先月|せんげつ]から[料理|りょうり][教室|きょうしつ]に[通|かよ]っています。[最初|さいしょ]は[簡単|かんたん]な[料理|りょうり]しか[作|つく]れませんでしたが、[今|いま]は[魚|さかな]の[料理|りょうり]も[作|つく]れるようになりました。[来月|らいげつ]は[友達|ともだち]を[家|いえ]に[呼|よ]んで、[習|なら]った[料理|りょうり]を[作|つく]ってあげるつもりです。",
