  "朝の三十分": "[朝|あさ]の[三|さん][十|じゅう][分|ふん]",
  "去年の春から、私はいつもより三十分早く起きるようにしている。きっかけは、会社に遅れそうになって駅まで走った日のことだ。駅に着いたときには息が切れて、一日が始まる前にもう疲れていた。電車の中で汗をかきながら、「毎朝こんなに急いでいて、本当にいいのだろうか」と考えた。": "[去年|きょねん]の[春|はる]から、[私|わたし]はいつもより[三|さん][十|じゅう][分|ふん][早|はや]く[起|お]きるようにしている。きっかけは、[会社|かいしゃ]に[遅|おく]れそうになって[駅|えき]まで[走|はし]った[日|ひ]のことだ。[駅|えき]に[着|つ]いたときには[息|いき]が[切|き]れて、[一|いち][日|にち]が[始|はじ]まる[前|まえ]にもう[疲|つか]れていた。[電車|でんしゃ]の[中|なか]で[汗|あせ]をかきながら、「[毎朝|まいあさ]こんなに[急|いそ]いでいて、[本当|ほんとう]にいいのだろうか」と[考|かんが]えた。",
  "最初の一週間は本当につらかった。目覚まし時計が鳴っても、なかなか布団から出られない。しかし、夜は早く寝るように気をつけると、少しずつ体が慣れてきた。今では、目覚まし時計が鳴る前に目が覚めることもある。": "[最初|さいしょ]の[一週間|いっしゅうかん]は[本当|ほんとう]につらかった。[目覚|めざ]まし[時計|とけい]が[鳴|な]っても、なかなか[布団|ふとん]から[出|で]られない。しかし、[夜|よる]は[早|はや]く[寝|ね]るように[気|き]をつけると、[少|すこ]しずつ[体|からだ]が[慣|な]れてきた。[今|いま]では、[目覚|めざ]まし[時計|とけい]が[鳴|な]る[前|まえ]に[目|め]が[覚|さ]めることもある。",
  "増えた三十分で、私は特別なことをしているわけではない。コーヒーをゆっくり飲んだり、窓の外を眺めたり、日記を書いたりするだけだ。それでも、一日の始まりに自分のための時間があると、気持ちに余裕が生まれる。仕事で嫌なことがあっても、以前ほどいらいらしなくなった。": "[増|ふ]えた[三|さん][十|じゅう][分|ふん]で、[私|わたし]は[特別|とくべつ]なことをしているわけではない。コーヒーをゆっくり[飲|の]んだり、[窓|まど]の[外|そと]を[眺|なが]めたり、[日記|にっき]を[書|か]いたりするだけだ。それでも、[一|いち][日|にち]の[始|はじ]まりに[自分|じぶん]のための[時間|じかん]があると、[気持|きも]ちに[余裕|よゆう]が[生|う]まれる。[仕事|しごと]で[嫌|いや]なことがあっても、[以前|いぜん]ほどいらいらしなくなった。",
  "もちろん、早起きがすべての人に合うとは限らない。夜のほうが集中できる人もいるだろう。大切なのは、自分に合った生活のリズムを見つけることだと思う。私にとって、それが朝の三十分だったのだ。": "もちろん、[早起|はやお]きがすべての[人|ひと]に[合|あ]うとは[限|かぎ]らない。[夜|よる]のほうが[集中|しゅうちゅう]できる[人|ひと]もいるだろう。[大切|たいせつ]なのは、[自分|じぶん]に[合|あ]った[生活|せいかつ]のリズムを[見|み]つけることだと[思|おも]う。[私|わたし]にとって、それが[朝|あさ]の[三|さん][十|じゅう][分|ふん]だったのだ。",
  "筆者が早起きを始めたきっかけは何か。": "[筆者|ひっしゃ]が[早起|はやお]きを[始|はじ]めたきっかけは[何|なに]か。",
