  "ごみの出し方が変わります": "ごみの[出|だ]し[方|かた]が[変|か]わります",
  "さくら台マンションにお住まいの皆様へ。いつもごみ置き場をきれいに使っていただき、ありがとうございます。来月一日から市のルールが変わるため、このマンションのごみの出し方も一部変更になります。以下の内容をよくお読みください。": "さくら[台|だい]マンションにお[住|す]まいの[皆様|みなさま]へ。いつもごみ[置き場|おきば]をきれいに[使|つか]っていただき、ありがとうございます。[来月|らいげつ][一|いち][日|にち]から[市|し]のルールが[変|か]わるため、このマンションのごみの[出|だ]し[方|かた]も[一部|いちぶ][変更|へんこう]になります。[以下|いか]の[内容|ないよう]をよくお[読|よ]みください。",
  "まず、プラスチックごみの日が、これまでの水曜日から金曜日に変わります。また、ペットボトルはプラスチックごみとは別に集めることになりました。ペットボトルを出すときは、キャップとラベルを外し、中を軽く洗ってから、専用の青い箱に入れてください。": "まず、プラスチックごみの[日|ひ]が、これまでの[水曜日|すいようび]から[金曜日|きんようび]に[変|か]わります。また、ペットボトルはプラスチックごみとは[別|べつ]に[集|あつ]めることになりました。ペットボトルを[出|だ]すときは、キャップとラベルを[外|はず]し、[中|なか]を[軽|かる]く[洗|あら]ってから、[専用|せんよう]の[青|あお]い[箱|はこ]に[入|い]れてください。",
  "次に、ごみを出す時間についてです。最近、前の日の夜にごみを出す方がいらっしゃいますが、カラスに袋を破られて、ごみが散らかることが増えています。ごみは必ず当日の朝八時までに出してください。夜に出すことはご遠慮ください。": "[次|つぎ]に、ごみを[出|だ]す[時間|じかん]についてです。[最近|さいきん]、[前|まえ]の[日|ひ]の[夜|よる]にごみを[出|だ]す[方|ほう]がいらっしゃいますが、カラスに[袋|ふくろ]を[破|やぶ]られて、ごみが[散|ち]らかることが[増|ふ]えています。ごみは[必|かなら]ず[当日|とうじつ]の[朝|あさ][八時|はちじ]までに[出|だ]してください。[夜|よる]に[出|だ]すことはご[遠慮|えんりょ]ください。",
  "新しいルールについてわからないことがあれば、管理人室までお気軽にお問い合わせください。管理人は月曜日から土曜日の午前九時から午後五時までおります。住みやすいマンションにするために、皆様のご協力をよろしくお願いいたします。さくら台マンション管理組合": "[新|あたら]しいルールについてわからないことがあれば、[管理|かんり][人|じん][室|しつ]までお[気軽|きがる]にお[問い合|といあ]わせください。[管理|かんり][人|じん]は[月曜日|げつようび]から[土曜日|どようび]の[午前|ごぜん][九時|くじ]から[午後|ごご][五時|ごじ]までおります。[住|す]みやすいマンションにするために、[皆様|みなさま]のご[協力|きょうりょく]をよろしくお[願|ねが]いいたします。さくら[台|だい]マンション[管理|かんり][組合|くみあい]",
  "来月から、ペットボトルはどう出せばよいか。": "[来月|らいげつ]から、ペットボトルはどう[出|だ]せばよいか。",
