  "前の日の夜に管理人室に持っていく": "[前|まえ]の[日|ひ]の[夜|よる]に[管理|かんり][人|じん][室|しつ]に[持|も]っていく",
  "このお知らせによると、してはいけないことはどれか。": "このお[知|し]らせによると、してはいけないことはどれか。",
