  "風呂敷のよさ": "[風呂敷|ふろしき]のよさ",
  "皆さんは「風呂敷」を使ったことがありますか。風呂敷は、物を包んだり運んだりするための四角い布です。昔、お風呂に行くときに服を包んだり、床に敷いたりしていたので、この名前がついたと言われています。": "[皆|みな]さんは「[風呂敷|ふろしき]」を[使|つか]ったことがありますか。[風呂敷|ふろしき]は、[物|もの]を[包|つつ]んだり[運|はこ]んだりするための[四角|しかく]い[布|ぬの]です。[昔|むかし]、お[風呂|ふろ]に[行|い]くときに[服|ふく]を[包|つつ]んだり、[床|ゆか]に[敷|し]いたりしていたので、この[名前|なまえ]がついたと[言|い]われています。",
  "今では紙袋やレジ袋が広く使われるようになり、風呂敷を持っている若い人は少なくなりました。しかし、最近、風呂敷がもう一度注目されています。理由の一つは、何度でも使えるので、ごみを減らすことができるからです。": "[今|いま]では[紙袋|かみぶくろ]やレジ[袋|ぶくろ]が[広|ひろ]く[使|つか]われるようになり、[風呂敷|ふろしき]を[持|も]っている[若|わか]い[人|ひと]は[少|すく]なくなりました。しかし、[最近|さいきん]、[風呂敷|ふろしき]がもう[一度|いちど][注目|ちゅうもく]されています。[理由|りゆう]の[一|ひと]つは、[何|なん][度|ど]でも[使|つか]えるので、ごみを[減|へ]らすことができるからです。",
  "風呂敷のいいところは、包む物の形を選ばないことです。箱はもちろん、瓶や本、丸い果物でも、結び方を工夫すれば上手に包めます。使わないときは小さくたたんで、かばんに入れておけます。また、きれいな柄の風呂敷は、テーブルにかけたり、壁に飾ったりすることもできます。": "[風呂敷|ふろしき]のいいところは、[包|つつ]む[物|もの]の[形|かたち]を[選|えら]ばないことです。[箱|はこ]はもちろん、[瓶|びん]や[本|ほん]、[丸|まる]い[果物|くだもの]でも、[結び方|むすびかた]を[工夫|くふう]すれば[上手|じょうず]に[包|つつ]めます。[使|つか]わないときは[小|ちい]さくたたんで、かばんに[入|い]れておけます。また、きれいな[柄|え]の[風呂敷|ふろしき]は、テーブルにかけたり、[壁|かべ]に[飾|かざ]ったりすることもできます。",
  "私も去年、祖母から古い風呂敷をもらいました。初めは結び方がわからず、何度も失敗しましたが、今では買い物のときに欠かせない物になっています。昔の人の知恵は、今の生活にも十分役に立つのだと感じています。": "[私|わたし]も[去年|きょねん]、[祖母|そぼ]から[古|ふる]い[風呂敷|ふろしき]をもらいました。[初|はじ]めは[結び方|むすびかた]がわからず、[何|なん][度|ど]も[失敗|しっぱい]しましたが、[今|いま]では[買い物|かいもの]のときに[欠|か]かせない[物|もの]になっています。[昔|むかし]の[人|ひと]の[知恵|ちえ]は、[今|いま]の[生活|せいかつ]にも[十分|じゅうぶん][役に立|やくにた]つのだと[感|かん]じています。",
  "風呂敷が最近また注目されている理由として、文章で挙げられているのはどれか。": "[風呂敷|ふろしき]が[最近|さいきん]また[注目|ちゅうもく]されている[理由|りゆう]として、[文章|ぶんしょう]で[挙|あ]げられているのはどれか。",
  "何度でも使えて、ごみを減らせるから": "[何|なん][度|ど]でも[使|つか]えて、ごみを[減|へ]らせるから",
  "紙袋より値段が安いから": "[紙袋|かみぶくろ]より[値段|ねだん]が[安|やす]いから",
