  "夏祭りの太鼓": "[夏|なつ][祭|まつ]りの[太鼓|たいこ]",
  "僕が生まれた町では、毎年八月に小さな夏祭りがある。祭りの夜には、町の子どもたちが大きな太鼓をたたきながら、神社までの道を歩く。小学生のころの僕は、その太鼓の音を聞くと、胸がどきどきしたものだ。": "[僕|ぼく]が[生|う]まれた[町|まち]では、[毎年|まいとし][八月|はちがつ]に[小|ちい]さな[夏|なつ][祭|まつ]りがある。[祭|まつ]りの[夜|よる]には、[町|まち]の[子|こ]どもたちが[大|おお]きな[太鼓|たいこ]をたたきながら、[神社|じんじゃ]までの[道|みち]を[歩|ある]く。[小学生|しょうがくせい]のころの[僕|ぼく]は、その[太鼓|たいこ]の[音|おと]を[聞|き]くと、[胸|むね]がどきどきしたものだ。",
  "大学に入って東京で一人暮らしを始めてから、祭りのことはほとんど思い出さなくなった。ところが、今年の夏、母から電話がかかってきた。「太鼓をたたく子どもが足りなくて、今年で祭りをやめるかもしれない」と言うのだ。町では若い人が減り、子どもの数も年々少なくなっているらしい。": "[大学|だいがく]に[入|はい]って[東京|とうきょう]で[一人|ひとり][暮|く]らしを[始|はじ]めてから、[祭|まつ]りのことはほとんど[思い出|おもいだ]さなくなった。ところが、[今年|ことし]の[夏|なつ]、[母|はは]から[電話|でんわ]がかかってきた。「[太鼓|たいこ]をたたく[子|こ]どもが[足|た]りなくて、[今年|ことし]で[祭|まつ]りをやめるかもしれない」と[言|い]うのだ。[町|まち]では[若|わか]い[人|ひと]が[減|へ]り、[子|こ]どもの[数|かず]も[年々|ねんねん][少|すく]なくなっているらしい。",
  "僕は迷ったが、休みを取って町に帰ることにした。そして、子どもたちと一緒に太鼓の練習をした。久しぶりにたたいた太鼓は思ったより重く、腕がすぐに痛くなった。それでも、子どもたちが真剣な顔で練習する様子を見ていると、昔の自分を見ているような気がした。": "[僕|ぼく]は[迷|まよ]ったが、[休|やす]みを[取|と]って[町|まち]に[帰|かえ]ることにした。そして、[子|こ]どもたちと[一緒|いっしょ]に[太鼓|たいこ]の[練習|れんしゅう]をした。[久|ひさ]しぶりにたたいた[太鼓|たいこ]は[思|おも]ったより[重|おも]く、[腕|うで]がすぐに[痛|いた]くなった。それでも、[子|こ]どもたちが[真剣|しんけん]な[顔|かお]で[練習|れんしゅう]する[様子|ようす]を[見|み]ていると、[昔|むかし]の[自分|じぶん]を[見|み]ているような[気|き]がした。",
  "祭りの夜、太鼓の音は町中に響いた。見に来たお年寄りの中には、涙を流している人もいた。祭りが終わったあと、一人の男の子が「来年も来てくれる？」と聞いてきた。僕は少し考えてから、「もちろん」と答えた。": "[祭|まつ]りの[夜|よる]、[太鼓|たいこ]の[音|おと]は[町中|まちなか]に[響|ひび]いた。[見|み]に[来|き]たお[年寄|としよ]りの[中|なか]には、[涙|なみだ]を[流|なが]している[人|ひと]もいた。[祭|まつ]りが[終|お]わったあと、[一人|ひとり]の[男の子|おとこのこ]が「[来年|らいねん]も[来|き]てくれる？」と[聞|き]いてきた。[僕|ぼく]は[少|すこ]し[考|かんが]えてから、「もちろん」と[答|こた]えた。",
  "母が電話をかけてきたのはなぜか。": "[母|はは]が[電話|でんわ]をかけてきたのはなぜか。",
  "子どもが足りず、祭りがなくなるかもしれないと伝えるため": "[子|こ]どもが[足|た]りず、[祭|まつ]りがなくなるかもしれないと[伝|つた]えるため",
