  "太鼓が壊れたことを知らせるため": "[太鼓|たいこ]が[壊|こわ]れたことを[知|し]らせるため",
  "東京に遊びに行きたかったため": "[東京|とうきょう]に[遊|あそ]びに[行|い]きたかったため",
  "練習のとき、「僕」はどう感じたか。": "[練習|れんしゅう]のとき、「[僕|ぼく]」はどう[感|かん]じたか。",
  "子どもたちを見て、昔の自分を見ているようだと感じた": "[子|こ]どもたちを[見|み]て、[昔|むかし]の[自分|じぶん]を[見|み]ているようだと[感|かん]じた",
  "太鼓が軽くて簡単だと感じた": "[太鼓|たいこ]が[軽|かる]くて[簡単|かんたん]だと[感|かん]じた",
  "練習がつまらなくて帰りたくなった": "[練習|れんしゅう]がつまらなくて[帰|かえ]りたくなった",
  "子どもたちが真剣ではないので腹が立った": "[子|こ]どもたちが[真剣|しんけん]ではないので[腹|はら]が[立|た]った",
  "町の本屋を守るには": "[町|まち]の[本屋|ほんや]を[守|まも]るには",
  "最近、町から小さな本屋が次々と消えている。インターネットで本を注文すれば、次の日には家に届く。電子書籍なら、スマホ一つで何百冊も持ち歩ける。便利な時代になったのだから、本屋が減るのは仕方がないことなのかもしれない。": "[最近|さいきん]、[町|まち]から[小|ちい]さな[本屋|ほんや]が[次々|つぎつぎ]と[消|き]えている。インターネットで[本|ほん]を[注文|ちゅうもん]すれば、[次|つぎ]の[日|ひ]には[家|いえ]に[届|とど]く。[電子|でんし][書籍|しょせき]なら、スマホ[一|ひと]つで[何|なん][百|ひゃく][冊|さつ]も[持ち歩|もちある]ける。[便利|べんり]な[時代|じだい]になったのだから、[本屋|ほんや]が[減|へ]るのは[仕方|しかた]がないことなのかもしれない。",
  "しかし、本屋には、ネットにはない良さがあると私は思う。それは、探していなかった本に出会えることだ。目的の本を探して棚の間を歩いていると、ふと気になる表紙が目に入る。手に取って数ページ読んでみたら面白くて、結局その本も買ってしまう。そんな経験をした人は多いだろう。": "しかし、[本屋|ほんや]には、ネットにはない[良|よ]さがあると[私|わたし]は[思|おも]う。それは、[探|さが]していなかった[本|ほん]に[出会|であ]えることだ。[目的|もくてき]の[本|ほん]を[探|さが]して[棚|たな]の[間|あいだ]を[歩|ある]いていると、ふと[気|き]になる[表紙|ひょうし]が[目|め]に[入|はい]る。[手|て]に[取|と]って[数|すう]ページ[読|よ]んでみたら[面白|おもしろ]くて、[結局|けっきょく]その[本|ほん]も[買|か]ってしまう。そんな[経験|けいけん]をした[人|ひと]は[多|おお]いだろう。",
  "私の家の近くにある本屋は、店長がとても工夫をしている。おすすめの本には手書きのカードをつけ、月に一度は作家を招いて小さな会を開く。週末には子どもに絵本を読む時間もあり、いつも親子連れでにぎやかだ。売り上げは決して多くないそうだが、地域の人が集まる場所になっている。": "[私|わたし]の[家|いえ]の[近|ちか]くにある[本屋|ほんや]は、[店長|てんちょう]がとても[工夫|くふう]をしている。おすすめの[本|ほん]には[手書|てが]きのカードをつけ、[月|つき]に[一度|いちど]は[作家|さっか]を[招|まね]いて[小|ちい]さな[会|かい]を[開|ひら]く。[週末|しゅうまつ]には[子|こ]どもに[絵本|えほん]を[読|よ]む[時間|じかん]もあり、いつも[親子|おやこ][連|づ]れでにぎやかだ。[売り上|うりあ]げは[決|けっ]して[多|おお]くないそうだが、[地域|ちいき]の[人|ひと]が[集|あつ]まる[場所|ばしょ]になっている。",
  "本屋を守るために、私たちにできることは何だろうか。難しく考える必要はない。たまには近くの本屋に足を運んで、一冊でもいいから本を買うことだ。それが、町の文化を守る小さな一歩になると私は信じている。": "[本屋|ほんや]を[守|まも]るために、[私|わたし]たちにできることは[何|なに]だろうか。[難|むずか]しく[考|かんが]える[必要|ひつよう]はない。たまには[近|ちか]くの[本屋|ほんや]に[足|あし]を[運|はこ]んで、[一|いち][冊|さつ]でもいいから[本|ほん]を[買|か]うことだ。それが、[町|まち]の[文化|ぶんか]を[守|まも]る[小|ちい]さな[一|いち][歩|ほ]になると[私|わたし]は[信|しん]じている。",
  "筆者が考える本屋の良さは何か。": "[筆者|ひっしゃ]が[考|かんが]える[本屋|ほんや]の[良|よ]さは[何|なに]か。",
  "探していなかった本に出会えること": "[探|さが]していなかった[本|ほん]に[出会|であ]えること",
  "ネットより本が安く買えること": "ネットより[本|ほん]が[安|やす]く[買|か]えること",
  "次の日に家に届けてくれること": "[次|つぎ]の[日|ひ]に[家|いえ]に[届|とど]けてくれること",
  "何百冊も持ち歩けること": "[何|なん][百|ひゃく][冊|さつ]も[持ち歩|もちある]けること",
  "筆者の家の近くにある本屋について、正しいものはどれか。": "[筆者|ひっしゃ]の[家|いえ]の[近|ちか]くにある[本屋|ほんや]について、[正|ただ]しいものはどれか。",
  "月に一度、作家を招いて会を開いている": "[月|つき]に[一度|いちど]、[作家|さっか]を[招|まね]いて[会|かい]を[開|ひら]いている",
  "売り上げがとても多い": "[売り上|うりあ]げがとても[多|おお]い",
