  "筆者が読者にすすめていることは何か。": "[筆者|ひっしゃ]が[読者|どくしゃ]にすすめていることは[何|なに]か。",
  "近くの本屋に行って本を買うこと": "[近|ちか]くの[本屋|ほんや]に[行|い]って[本|ほん]を[買|か]うこと",
  "本屋でアルバイトをすること": "[本屋|ほんや]でアルバイトをすること",
  "電子書籍を読むのをやめること": "[電子|でんし][書籍|しょせき]を[読|よ]むのをやめること",
