  "二十度くらい": "[二|に][十|じゅう][度|ど]くらい",
  "筆者のアドバイスと合わないものはどれか。": "[筆者|ひっしゃ]のアドバイスと[合|あ]わないものはどれか。",
  "天気がよければ雨具は持たなくてよい": "[天気|てんき]がよければ[雨具|あまぐ]は[持|も]たなくてよい",
  "できるだけ朝早く出発する": "できるだけ[朝|あさ][早|はや]く[出発|しゅっぱつ]する",
  "午後の早い時間に下りるように計画する": "[午後|ごご]の[早|はや]い[時間|じかん]に[下|お]りるように[計画|けいかく]する",
  "おかしいと感じたら引き返す": "おかしいと[感|かん]じたら[引き返|ひきかえ]す",
  "夕焼けはなぜ赤いのか": "[夕焼|ゆうや]けはなぜ[赤|あか]いのか",
  "晴れた日の昼、空は青い。ところが夕方になると、西の空はオレンジ色や赤に変わる。同じ太陽の光なのに、どうして時間によって空の色が違うのだろうか。": "[晴|は]れた[日|ひ]の[昼|ひる]、[空|そら]は[青|あお]い。ところが[夕方|ゆうがた]になると、[西|にし]の[空|そら]はオレンジ[色|しょく]や[赤|あか]に[変|か]わる。[同|おな]じ[太陽|たいよう]の[光|ひかり]なのに、どうして[時間|じかん]によって[空|そら]の[色|いろ]が[違|ちが]うのだろうか。",
  "太陽の光は白く見えるが、実はいろいろな色の光が混ざってできている。虹が七色に見えるのはそのためだ。光が空気の中を通るとき、空気のとても小さなつぶにぶつかって、いろいろな方向に散らばる。このとき、青い光は赤い光よりも散らばりやすいという性質がある。": "[太陽|たいよう]の[光|ひかり]は[白|しろ]く[見|み]えるが、[実|じつ]はいろいろな[色|いろ]の[光|ひかり]が[混|ま]ざってできている。[虹|にじ]が[七|なな][色|しょく]に[見|み]えるのはそのためだ。[光|ひかり]が[空気|くうき]の[中|なか]を[通|とお]るとき、[空気|くうき]のとても[小|ちい]さなつぶにぶつかって、いろいろな[方向|ほうこう]に[散|ち]らばる。このとき、[青|あお]い[光|ひかり]は[赤|あか]い[光|ひかり]よりも[散|ち]らばりやすいという[性質|せいしつ]がある。",
  "昼間は太陽が高い位置にあるので、光が空気の中を通る距離は短い。散らばった青い光が空全体に広がるため、私たちの目には空が青く見える。一方、夕方は太陽が低い位置にあるので、光は空気の中を長い距離通ってくる。その間に青い光はほとんど散らばってしまい、散らばりにくい赤やオレンジの光だけが私たちの目に届く。これが夕焼けの正体だ。": "[昼間|ひるま]は[太陽|たいよう]が[高|たか]い[位置|いち]にあるので、[光|ひかり]が[空気|くうき]の[中|なか]を[通|とお]る[距離|きょり]は[短|みじか]い。[散|ち]らばった[青|あお]い[光|ひかり]が[空|そら][全体|ぜんたい]に[広|ひろ]がるため、[私|わたし]たちの[目|め]には[空|そら]が[青|あお]く[見|み]える。[一方|いっぽう]、[夕方|ゆうがた]は[太陽|たいよう]が[低|ひく]い[位置|いち]にあるので、[光|ひかり]は[空気|くうき]の[中|なか]を[長|なが]い[距離|きょり][通|かよ]ってくる。その[間|かん]に[青|あお]い[光|ひかり]はほとんど[散|ち]らばってしまい、[散|ち]らばりにくい[赤|あか]やオレンジの[光|ひかり]だけが[私|わたし]たちの[目|め]に[届|とど]く。これが[夕焼|ゆうや]けの[正体|しょうたい]だ。",
  "ちなみに、火星の夕焼けは青く見えるそうだ。火星の空気には細かい砂がたくさん含まれていて、地球とは光の散らばり方が違うからである。いつも見ている空も、理由を知ると少し違って見えてくるのではないだろうか。": "ちなみに、[火星|かせい]の[夕焼|ゆうや]けは[青|あお]く[見|み]えるそうだ。[火星|かせい]の[空気|くうき]には[細|こま]かい[砂|すな]がたくさん[含|ふく]まれていて、[地球|ちきゅう]とは[光|ひかり]の[散|ち]らばり[方|かた]が[違|ちが]うからである。いつも[見|み]ている[空|そら]も、[理由|りゆう]を[知|し]ると[少|すこ]し[違|ちが]って[見|み]えてくるのではないだろうか。",
  "青い光にはどのような性質があるか。": "[青|あお]い[光|ひかり]にはどのような[性質|せいしつ]があるか。",
  "赤い光よりも散らばりやすい": "[赤|あか]い[光|ひかり]よりも[散|ち]らばりやすい",
  "赤い光よりも遠くまで届く": "[赤|あか]い[光|ひかり]よりも[遠|とお]くまで[届|とど]く",
  "空気のつぶにぶつからない": "[空気|くうき]のつぶにぶつからない",
  "夕方だけ強くなる": "[夕方|ゆうがた]だけ[強|つよ]くなる",
  "夕方、空が赤く見えるのはなぜか。": "[夕方|ゆうがた]、[空|そら]が[赤|あか]く[見|み]えるのはなぜか。",
  "光が長い距離を通る間に、青い光が散らばってしまうから": "[光|ひかり]が[長|なが]い[距離|きょり]を[通|とお]る[間|ま]に、[青|あお]い[光|ひかり]が[散|ち]らばってしまうから",
  "夕方は太陽そのものが赤くなるから": "[夕方|ゆうがた]は[太陽|たいよう]そのものが[赤|あか]くなるから",
