  "壊れた物がまだ見つかっていなかったから": "[壊|こわ]れた[物|もの]がまだ[見|み]つかっていなかったから",
  "鈴木さんは何のために部室に来たか。": "[鈴木|すずき]さんは[何|なに]のために[部室|ぶしつ]に[来|き]たか。",
  "借りていたノートを返すため": "[借|か]りていたノートを[返|かえ]すため",
  "お弁当を食べるため": "お[弁当|べんとう]を[食|た]べるため",
  "絵の道具を取るため": "[絵|え]の[道具|どうぐ]を[取|と]るため",
