  "高橋君。壊れた物がガラスだと知っていたから": "[高橋|たかはし][君|くん]。[壊|こわ]れた[物|もの]がガラスだと[知|し]っていたから",
  "佐藤君。十二時半に部室に来たから": "[佐藤|さとう][君|くん]。[十二時|じゅうにじ][半|はん]に[部室|ぶしつ]に[来|き]たから",
