  "高橋君。部室でお弁当を食べていたから": "[高橋|たかはし][君|くん]。[部室|ぶしつ]でお[弁当|べんとう]を[食|た]べていたから",
  "雨の夜の喫茶店": "[雨|あめ]の[夜|よる]の[喫茶店|きっさてん]",
  "叔父は昔、警察で働いていた。今は退職して、町で小さな喫茶店をしている。ある雨の夜、近所の和菓子屋の主人、松本さんが店に飛び込んできた。「レジのお金がなくなったんです。どうしたらいいでしょう」": "[叔父|おじ]は[昔|むかし]、[警察|けいさつ]で[働|はたら]いていた。[今|いま]は[退職|たいしょく]して、[町|まち]で[小|ちい]さな[喫茶店|きっさてん]をしている。ある[雨|あめ]の[夜|よる]、[近所|きんじょ]の[和菓子|わがし][屋|や]の[主人|しゅじん]、[松本|まつもと]さんが[店|みせ]に[飛び込|とびこ]んできた。「レジのお[金|かね]がなくなったんです。どうしたらいいでしょう」",
  "松本さんの話によると、店を閉めたのは午後六時。レジのお金を数えて袋に入れたあと、奥の部屋で十分ほど電話をしていた。戻ってくると、お金が入った袋が消えていたという。その日に働いていたのは、アルバイトの山口さんと、店員の川田さんの二人だ。": "[松本|まつもと]さんの[話|はなし]によると、[店|みせ]を[閉|し]めたのは[午後|ごご][六時|ろくじ]。レジのお[金|かね]を[数|かぞ]えて[袋|ふくろ]に[入|い]れたあと、[奥|おく]の[部屋|へや]で[十|じゅう][分|ふん]ほど[電話|でんわ]をしていた。[戻|もど]ってくると、お[金|かね]が[入|はい]った[袋|ふくろ]が[消|き]えていたという。その[日|ひ]に[働|はたら]いていたのは、アルバイトの[山口|やまぐち]さんと、[店員|てんいん]の[川田|かわた]さんの[二人|ふたり]だ。",
  "山口さんは「六時に店を出て、六時五分のバスで家に帰りました」と話したそうだ。川田さんは「五時半に仕事が終わって、すぐに歩いて帰りました。家に着いたのは六時ごろです。途中で雨が降り出して、びしょぬれになりましたよ」と言ったらしい。": "[山口|やまぐち]さんは「[六時|ろくじ]に[店|みせ]を[出|で]て、[六時|ろくじ][五分|ごふん]のバスで[家|いえ]に[帰|かえ]りました」と[話|はな]したそうだ。[川田|かわた]さんは「[五時|ごじ][半|はん]に[仕事|しごと]が[終|お]わって、すぐに[歩|ある]いて[帰|かえ]りました。[家|いえ]に[着|つ]いたのは[六時|ろくじ]ごろです。[途中|とちゅう]で[雨|あめ]が[降り出|ふりだ]して、びしょぬれになりましたよ」と[言|い]ったらしい。",
  "叔父はコーヒーを一口飲んで、窓の外を見た。「松本さん、今日、雨が降り始めたのは何時ごろでしたか」「たしか六時半ごろです。電話をしているとき、窓に雨の当たる音がしましたから」。叔父は静かにうなずいた。「どうやら、うそをついている人がいるようですね」": "[叔父|おじ]はコーヒーを[一|いち][口|くち][飲|の]んで、[窓|まど]の[外|そと]を[見|み]た。「[松本|まつもと]さん、[今日|きょう]、[雨|あめ]が[降|ふ]り[始|はじ]めたのは[何時|なんじ]ごろでしたか」「たしか[六時|ろくじ][半|はん]ごろです。[電話|でんわ]をしているとき、[窓|まど]に[雨|あめ]の[当|あ]たる[音|おと]がしましたから」。[叔父|おじ]は[静|しず]かにうなずいた。「どうやら、うそをついている[人|ひと]がいるようですね」",
  "松本さんがお金がないことに気づいたのはいつか。": "[松本|まつもと]さんがお[金|かね]がないことに[気|き]づいたのはいつか。",
  "奥の部屋で電話をして、戻ってきたとき": "[奥|おく]の[部屋|へや]で[電話|でんわ]をして、[戻|もど]ってきたとき",
  "朝、店を開けたとき": "[朝|あさ]、[店|みせ]を[開|あ]けたとき",
