  "叔父の喫茶店に来たとき": "[叔父|おじ]の[喫茶店|きっさてん]に[来|き]たとき",
  "この日、雨が降り始めたのは何時ごろか。": "この[日|ひ]、[雨|あめ]が[降|ふ]り[始|はじ]めたのは[何時|なんじ]ごろか。",
  "六時半ごろ": "[六時|ろくじ][半|はん]ごろ",
