  "うそをついているのはだれか。また、その理由は何か。": "うそをついているのはだれか。また、その[理由|りゆう]は[何|なに]か。",
  "川田さん。六時ごろ家に着いたのに、帰る途中で雨にぬれたと言ったから": "[川田|かわた]さん。[六時|ろくじ]ごろ[家|か]に[着|つ]いたのに、[帰|かえ]る[途中|とちゅう]で[雨|あめ]にぬれたと[言|い]ったから",
  "山口さん。六時五分にはバスが走っていないから": "[山口|やまぐち]さん。[六時|ろくじ][五分|ごふん]にはバスが[走|はし]っていないから",
  "松本さん。電話をしていたと言ったから": "[松本|まつもと]さん。[電話|でんわ]をしていたと[言|い]ったから",
