  "警察が 来た（　）、犯人は 窓から 逃げた。": "[警察|けいさつ]が [来|き]た（　）、[犯人|はんにん]は [窓|まど]から [逃|に]げた。",
  "この なぞは 子ども（　）解ける ほど 簡単だ。": "この なぞは [子|こ]ども（　）[解|と]ける ほど [簡単|かんたん]だ。",
