  "盗む": "[盗|ぬす]む",
  "信じる": "[信|しん]じる",
  "守る": "[守|まも]る",
  "彼は 本当の ことを 知っている（　）、何も 言わなかった。": "[彼|かれ]は [本当|ほんとう]の ことを [知|し]っている（　）、[何|なに]も [言|い]わなかった。",
  "雨が 降らない（　）、早く 帰ろう。": "[雨|あめ]が [降|ふ]らない（　）、[早|はや]く [帰|かえ]ろう。",
  "このカフェについて正しいものはどれか。": "このカフェについて[正|ただ]しいものはどれか。",
  "最近、駅前に新しいカフェができた。店内は静かで、勉強や仕事をする客が多い。ただ、昼の十二時から一時までは込むので、その時間は席を使えるのは一時間までと決められている。": "[最近|さいきん]、[駅前|えきまえ]に[新|あたら]しいカフェができた。[店内|てんない]は[静|しず]かで、[勉強|べんきょう]や[仕事|しごと]をする[客|きゃく]が[多|おお]い。ただ、[昼|ひる]の[十二時|じゅうにじ]から[一時|いちじ]までは[込|こ]むので、その[時間|じかん]は[席|せき]を[使|つか]えるのは[一時間|いちじかん]までと[決|き]められている。",
  "昼の 時間は 一時間までしか 席を 使えない": "[昼|ひる]の [時間|じかん]は [一時間|いちじかん]までしか [席|せき]を [使|つか]えない",
  "一日中 込んで いる": "[一日中|いちにちじゅう] [込|こ]んで いる",
