  "夜は 一時間しか 開いて いない": "[夜|よる]は [一時間|いちじかん]しか [開|ひら]いて いない",
  "このカフェに多いのはどんな客か。": "このカフェに[多|おお]いのはどんな[客|きゃく]か。",
  "勉強や 仕事を する 客": "[勉強|べんきょう]や [仕事|しごと]を する [客|きゃく]",
  "友達と 話す 客": "[友達|ともだち]と [話|はな]す [客|きゃく]",
  "食事を する 客": "[食事|しょくじ]を する [客|きゃく]",
  "本を 買う 客": "[本|ほん]を [買|か]う [客|きゃく]",
  "近所の人が見たのは何か。": "[近所|きんじょ]の[人|ひと]が[見|み]たのは[何|なに]か。",
  "事件の夜、山本さんは「十時には家で寝ていた」と言った。しかし、近所の人は十時半ごろ、山本さんの家の電気がついているのを見ていた。また、山本さんの靴には、現場の近くにしかない赤い土がついていた。": "[事件|じけん]の[夜|よる]、[山本|やまもと]さんは「[十時|じゅうじ]には[家|いえ]で[寝|ね]ていた」と[言|い]った。しかし、[近所|きんじょ]の[人|ひと]は[十時|じゅうじ][半|はん]ごろ、[山本|やまもと]さんの[家|いえ]の[電気|でんき]がついているのを[見|み]ていた。また、[山本|やまもと]さんの[靴|くつ]には、[現場|げんば]の[近|ちか]くにしかない[赤|あか]い[土|ど]がついていた。",
  "十時半ごろ 家の 電気が ついて いた": "[十時|じゅうじ][半|はん]ごろ [家|いえ]の [電気|でんき]が ついて いた",
