  "町の どこにでも ある": "[町|まち]の どこにでも ある",
  "近所の 人の 家に ある": "[近所|きんじょ]の [人|ひと]の [家|いえ]に ある",
  "電車の中で電話で話してはいけない理由は何か。": "[電車|でんしゃ]の[中|なか]で[電話|でんわ]で[話|はな]してはいけない[理由|りゆう]は[何|なに]か。",
  "日本では、電車の中で電話で話すのはマナー違反だと考えられている。メールを送ったり、インターネットを見たりするのは問題ないが、話す声がほかの客の迷惑になるからだ。急な用事の場合は、次の駅で降りてから電話をかける人が多い。": "[日本|にほん]では、[電車|でんしゃ]の[中|なか]で[電話|でんわ]で[話|はな]すのはマナー[違反|いはん]だと[考|かんが]えられている。メールを[送|おく]ったり、インターネットを[見|み]たりするのは[問題|もんだい]ないが、[話|はな]す[声|こえ]がほかの[客|きゃく]の[迷惑|めいわく]になるからだ。[急|きゅう]な[用事|ようじ]の[場合|ばあい]は、[次|つぎ]の[駅|えき]で[降|お]りてから[電話|でんわ]をかける[人|ひと]が[多|おお]い。",
