  "市民マラソン大会のお知らせ\n日時：十月十日（日）午前九時スタート\n※雨の場合は十七日（日）に延期します。\n参加したい人は、九月三十日までにインターネットで申し込んでください。当日の申し込みはできません。": "[市民|しみん]マラソン[大会|たいかい]のお[知|し]らせ\n[日時|にちじ]：[十月|じゅうがつ][十日|とおか]（[日|ひ]）[午前|ごぜん][九時|くじ]スタート\n※[雨|あめ]の[場合|ばあい]は[十|じゅう][七日|なのか]（[日|ひ]）に[延期|えんき]します。\n[参加|さんか]したい[人|ひと]は、[九月|くがつ][三|さん][十日|とおか]までにインターネットで[申し込|もうしこ]んでください。[当日|とうじつ]の[申し込|もうしこ]みはできません。",
