  "お帰りの際に": "お[帰|かえ]りの[際|さい]に",
  "お近くにお越しの折には、ぜひお立ち寄りください。": "お[近|ちか]くにお[越|こ]しの[折|おり]には、ぜひお[立ち寄|たちよ]りください。",
