  "言われるままに": "[言|い]われるままに",
  "二人は抜きつ抜かれつの勝負を続けた。": "[二人|ふたり]は[抜|ぬ]きつ[抜|ぬ]かれつの[勝負|しょうぶ]を[続|つづ]けた。",
  "抜きつ抜かれつ": "[抜|ぬ]きつ[抜|ぬ]かれつ",
  "引っ越しやら仕事やらで、毎日忙しい。": "[引っ越|ひっこ]しやら[仕事|しごと]やらで、[毎日|まいにち][忙|いそが]しい。",
  "引っ越しやら仕事やら": "[引っ越|ひっこ]しやら[仕事|しごと]やら",
  "高いだの遠いだの、文句ばかり言う。": "[高|たか]いだの[遠|とお]いだの、[文句|もんく]ばかり[言|い]う。",
  "高いだの遠いだの": "[高|たか]いだの[遠|とお]いだの",
