  "振り向きもしない": "[振|ふ]り[向|む]きもしない",
  "鍵を持っていたのは彼だけだったわけだから、疑われて当然だ。": "[鍵|かぎ]を[持|も]っていたのは[彼|かれ]だけだったわけだから、[疑|うたが]われて[当然|とうぜん]だ。",
  "彼だけだったわけだから": "[彼|かれ]だけだったわけだから",
  "片付けられない理由": "[片付|かたづ]けられない[理由|りゆう]",
  "部屋を片付けようと決心しても、気がつくと元の散らかった状態に戻っている。そんな経験を持つ人は少なくないだろう。私自身もその一人で、毎年年末になると大掃除をするのだが、春になるころには机の上に書類や本が山のように積まれている。なぜ片付けた状態を保つことができないのだろうか。": "[部屋|へや]を[片付|かたづ]けようと[決心|けっしん]しても、[気|き]がつくと[元|もと]の[散|ち]らかった[状態|じょうたい]に[戻|もど]っている。そんな[経験|けいけん]を[持|も]つ[人|ひと]は[少|すく]なくないだろう。[私|わたし][自身|じしん]もその[一人|ひとり]で、[毎年|まいとし][年末|ねんまつ]になると[大|だい][掃除|そうじ]をするのだが、[春|はる]になるころには[机|つくえ]の[上|うえ]に[書類|しょるい]や[本|ほん]が[山|やま]のように[積|つ]まれている。なぜ[片付|かたづ]けた[状態|じょうたい]を[保|たも]つことができないのだろうか。",
  "ある整理の専門家によると、片付けが苦手な人の多くは「いつか使うかもしれない」という考えから物を捨てられないのだという。確かに、私の引き出しには何年も使っていない文房具や、もらったまま開けていない贈り物がたくさん入っている。もったいないと思う気持ちは悪くないが、使わない物を持ち続けることは、かえって物を大切にしていないことになるのではないか。": "ある[整理|せいり]の[専門|せんもん][家|か]によると、[片付|かたづ]けが[苦手|にがて]な[人|ひと]の[多|おお]くは「いつか[使|つか]うかもしれない」という[考|かんが]えから[物|もの]を[捨|す]てられないのだという。[確|たし]かに、[私|わたし]の[引き出|ひきだ]しには[何|なん][年|ねん]も[使|つか]っていない[文房具|ぶんぼうぐ]や、もらったまま[開|あ]けていない[贈り物|おくりもの]がたくさん[入|はい]っている。もったいないと[思|おも]う[気持|きも]ちは[悪|わる]くないが、[使|つか]わない[物|もの]を[持|も]ち[続|つづ]けることは、かえって[物|もの]を[大切|たいせつ]にしていないことになるのではないか。",
  "また、物の置き場所が決まっていないことも、散らかる原因の一つだそうだ。使った物をどこに戻せばいいのかわからなければ、とりあえず近くに置いてしまう。それが繰り返されるうちに、部屋はあっという間に散らかってしまうわけだ。逆に言えば、すべての物に「住所」を決めておけば、片付けは習慣として続けやすくなる。": "また、[物|もの]の[置き場|おきば][所|しょ]が[決|き]まっていないことも、[散|ち]らかる[原因|げんいん]の[一|ひと]つだそうだ。[使|つか]った[物|もの]をどこに[戻|もど]せばいいのかわからなければ、とりあえず[近|ちか]くに[置|お]いてしまう。それが[繰り返|くりかえ]されるうちに、[部屋|へや]はあっという[間|ま]に[散|ち]らかってしまうわけだ。[逆|ぎゃく]に[言|い]えば、すべての[物|もの]に「[住所|じゅうしょ]」を[決|き]めておけば、[片付|かたづ]けは[習慣|しゅうかん]として[続|つづ]けやすくなる。",
  "この話を聞いて、私は一度にすべてを片付けようとするのをやめることにした。一日に一つの引き出しだけを整理し、一年以上使っていない物は思い切って手放す。そして残した物には必ず置き場所を決める。始めてまだ一か月ほどだが、以前よりも探し物をする時間が減り、気持ちにも余裕が生まれたように感じている。": "この[話|はなし]を[聞|き]いて、[私|わたし]は[一度|いちど]にすべてを[片付|かたづ]けようとするのをやめることにした。[一|いち][日|にち]に[一|ひと]つの[引き出|ひきだ]しだけを[整理|せいり]し、[一|いち][年|ねん][以上|いじょう][使|つか]っていない[物|もの]は[思い切|おもいき]って[手放|てばな]す。そして[残|のこ]した[物|もの]には[必|かなら]ず[置|お]き[場所|ばしょ]を[決|き]める。[始|はじ]めてまだ[一か月|いっかげつ]ほどだが、[以前|いぜん]よりも[探|さが]し[物|ぶつ]をする[時間|じかん]が[減|へ]り、[気持|きも]ちにも[余裕|よゆう]が[生|う]まれたように[感|かん]じている。",
  "片付けとは、単に部屋をきれいにすることではなく、自分にとって本当に必要な物は何かを考えることなのかもしれない。物を減らすことで、生活そのものが少し軽くなったような気がする。": "[片付|かたづ]けとは、[単|たん]に[部屋|へや]をきれいにすることではなく、[自分|じぶん]にとって[本当|ほんとう]に[必要|ひつよう]な[物|もの]は[何|なに]かを[考|かんが]えることなのかもしれない。[物|もの]を[減|へ]らすことで、[生活|せいかつ]そのものが[少|すこ]し[軽|かる]くなったような[気|き]がする。",
  "専門家によると、部屋が散らかる原因の一つは何か。": "[専門|せんもん][家|か]によると、[部屋|へや]が[散|ち]らかる[原因|げんいん]の[一|ひと]つは[何|なに]か。",
