  "筆者は片付けをどのようなものだと考えているか。": "[筆者|ひっしゃ]は[片付|かたづ]けをどのようなものだと[考|かんが]えているか。",
  "自分に本当に必要な物は何かを考えること": "[自分|じぶん]に[本当|ほんとう]に[必要|ひつよう]な[物|もの]は[何|なに]かを[考|かんが]えること",
  "部屋を他人にきれいに見せること": "[部屋|へや]を[他人|たにん]にきれいに[見|み]せること",
