  "湯船の中で泳がないこと": "[湯船|ゆぶね]の[中|なか]で[泳|およ]がないこと",
  "湯船に入る前に体を洗うこと": "[湯船|ゆぶね]に[入|はい]る[前|まえ]に[体|からだ]を[洗|あら]うこと",
  "タオルを湯の中に入れないこと": "タオルを[湯|ゆ]の[中|なか]に[入|い]れないこと",
