  "無人販売所と信頼": "[無人|むじん][販売|はんばい][所|しょ]と[信頼|しんらい]",
  "田舎の道を車で走っていると、道端に小さな小屋が建っていて、野菜が並べられているのを見かけることがある。そこには店員はおらず、代金を入れる箱が置いてあるだけだ。いわゆる「無人販売所」である。客は自分で商品を選び、決められた金額を箱に入れて持ち帰る。": "[田舎|いなか]の[道|みち]を[車|くるま]で[走|はし]っていると、[道端|みちばた]に[小|ちい]さな[小屋|こや]が[建|た]っていて、[野菜|やさい]が[並|なら]べられているのを[見|み]かけることがある。そこには[店員|てんいん]はおらず、[代金|だいきん]を[入|い]れる[箱|はこ]が[置|お]いてあるだけだ。いわゆる「[無人|むじん][販売|はんばい][所|しょ]」である。[客|きゃく]は[自分|じぶん]で[商品|しょうひん]を[選|えら]び、[決|き]められた[金額|きんがく]を[箱|はこ]に[入|い]れて[持ち帰|もちかえ]る。",
  "外国から来た友人をこうした販売所に案内したところ、彼はとても驚いていた。誰も見ていないのに、なぜ人々はきちんとお金を払うのか、というのだ。彼の国では、このような売り方はとても考えられないらしい。言われてみれば、確かに不思議な仕組みである。": "[外国|がいこく]から[来|き]た[友人|ゆうじん]をこうした[販売|はんばい][所|しょ]に[案内|あんない]したところ、[彼|かれ]はとても[驚|おどろ]いていた。[誰|だれ]も[見|み]ていないのに、なぜ[人々|ひとびと]はきちんとお[金|かね]を[払|はら]うのか、というのだ。[彼|かれ]の[国|くに]では、このような[売|う]り[方|かた]はとても[考|かんが]えられないらしい。[言|い]われてみれば、[確|たし]かに[不思議|ふしぎ]な[仕組|しく]みである。",
  "もちろん、すべての客が正直だとは限らない。実際、お金を払わずに商品を持っていく人がいて困っているという話もよく耳にする。最近では、防犯カメラを設置したり、電子決済を導入したりする販売所も増えてきた。それでも多くの農家がこの方法を続けているのは、人件費がかからないうえに、売れ残りそうな野菜を少しでも無駄にせずに済むからだ。": "もちろん、すべての[客|きゃく]が[正直|しょうじき]だとは[限|かぎ]らない。[実際|じっさい]、お[金|かね]を[払|はら]わずに[商品|しょうひん]を[持|も]っていく[人|ひと]がいて[困|こま]っているという[話|はなし]もよく[耳|みみ]にする。[最近|さいきん]では、[防犯|ぼうはん]カメラを[設置|せっち]したり、[電子|でんし][決済|けっさい]を[導入|どうにゅう]したりする[販売|はんばい][所|しょ]も[増|ふ]えてきた。それでも[多|おお]くの[農家|のうか]がこの[方法|ほうほう]を[続|つづ]けているのは、[人件|じんけん][費|ひ]がかからないうえに、[売れ残|うれのこ]りそうな[野菜|やさい]を[少|すこ]しでも[無駄|むだ]にせずに[済|す]むからだ。",
  "しかし、この仕組みを支えているのは、経済的な理由だけではないだろう。売る側は「客は正直に払ってくれるはずだ」と信じ、買う側はその信頼を裏切りたくないと考える。お互いの顔は見えなくても、そこには目に見えない約束のようなものが存在している。": "しかし、この[仕組|しく]みを[支|ささ]えているのは、[経済|けいざい][的|てき]な[理由|りゆう]だけではないだろう。[売|う]る[側|がわ]は「[客|きゃく]は[正直|しょうじき]に[払|はら]ってくれるはずだ」と[信|しん]じ、[買|か]う[側|がわ]はその[信頼|しんらい]を[裏切|うらぎ]りたくないと[考|かんが]える。お[互|たが]いの[顔|かお]は[見|み]えなくても、そこには[目|め]に[見|み]えない[約束|やくそく]のようなものが[存在|そんざい]している。",
  "社会がどれほど便利になっても、人を信じる気持ちがなければ成り立たないものがある。小さな無人販売所は、そのことを静かに教えてくれているように思う。": "[社会|しゃかい]がどれほど[便利|べんり]になっても、[人|ひと]を[信|しん]じる[気持|きも]ちがなければ[成り立|なりた]たないものがある。[小|ちい]さな[無人|むじん][販売|はんばい][所|しょ]は、そのことを[静|しず]かに[教|おし]えてくれているように[思|おも]う。",
  "外国から来た友人が驚いたのはなぜか。": "[外国|がいこく]から[来|き]た[友人|ゆうじん]が[驚|おどろ]いたのはなぜか。",
  "誰も見ていないのに人々がお金を払うから": "[誰|だれ]も[見|み]ていないのに[人々|ひとびと]がお[金|かね]を[払|はら]うから",
  "野菜の値段がとても安かったから": "[野菜|やさい]の[値段|ねだん]がとても[安|やす]かったから",
  "道端に販売所がたくさんあったから": "[道端|みちばた]に[販売|はんばい][所|しょ]がたくさんあったから",
