  "農家が無人販売を続ける理由として、本文に書かれているものはどれか。": "[農家|のうか]が[無人|むじん][販売|はんばい]を[続|つづ]ける[理由|りゆう]として、[本文|ほんぶん]に[書|か]かれているものはどれか。",
  "人件費がかからないから": "[人件|じんけん][費|ひ]がかからないから",
