  "社会には人を信じる気持ちによって成り立つものがある": "[社会|しゃかい]には[人|ひと]を[信|しん]じる[気持|きも]ちによって[成り立|なりた]つものがある",
  "無人販売所にはもっと防犯対策が必要だ": "[無人|むじん][販売|はんばい][所|しょ]にはもっと[防犯|ぼうはん][対策|たいさく]が[必要|ひつよう]だ",
  "外国にも無人販売所を広めるべきだ": "[外国|がいこく]にも[無人|むじん][販売|はんばい][所|しょ]を[広|ひろ]めるべきだ",
  "電子決済をすべての店に導入するべきだ": "[電子|でんし][決済|けっさい]をすべての[店|みせ]に[導入|どうにゅう]するべきだ",
  "都会のカラス": "[都会|とかい]のカラス",
  "朝、ごみ置き場の近くを通ると、カラスが袋を破って中身を散らかしていることがある。そのため、カラスは迷惑な鳥として嫌われることが多い。しかし、カラスの行動を詳しく観察してみると、その頭の良さに驚かされる。": "[朝|あさ]、ごみ[置き場|おきば]の[近|ちか]くを[通|とお]ると、カラスが[袋|ふくろ]を[破|やぶ]って[中身|なかみ]を[散|ち]らかしていることがある。そのため、カラスは[迷惑|めいわく]な[鳥|とり]として[嫌|きら]われることが[多|おお]い。しかし、カラスの[行動|こうどう]を[詳|くわ]しく[観察|かんさつ]してみると、その[頭|あたま]の[良|よ]さに[驚|おどろ]かされる。",
  "たとえば、カラスは人の顔を見分けることができると言われている。自分に危害を加えた人のことは長い間覚えていて、その人が近づくと大きな声で鳴いて仲間に知らせるそうだ。また、硬いクルミの殻を割るために、わざと道路に置いて車にひかせるカラスがいるという報告もある。これほど複雑な行動ができる鳥は、ほかにあまり例がない。": "たとえば、カラスは[人|ひと]の[顔|かお]を[見分|みわ]けることができると[言|い]われている。[自分|じぶん]に[危害|きがい]を[加|くわ]えた[人|ひと]のことは[長|なが]い[間|あいだ][覚|おぼ]えていて、その[人|ひと]が[近|ちか]づくと[大|おお]きな[声|こえ]で[鳴|な]いて[仲間|なかま]に[知|し]らせるそうだ。また、[硬|かた]いクルミの[殻|から]を[割|われ]るために、わざと[道路|どうろ]に[置|お]いて[車|くるま]にひかせるカラスがいるという[報告|ほうこく]もある。これほど[複雑|ふくざつ]な[行動|こうどう]ができる[鳥|とり]は、ほかにあまり[例|れい]がない。",
  "カラスが都会で数を増やしたのは、人間の暮らしと深く関係している。都会には食べ物が豊富にあり、高いビルや公園の木は巣を作るのに都合がよい。つまり、カラスは人間が作り出した環境にうまく適応した結果、私たちの身近に住むようになったのである。": "カラスが[都会|とかい]で[数|かず]を[増|ふ]やしたのは、[人間|にんげん]の[暮|く]らしと[深|ふか]く[関係|かんけい]している。[都会|とかい]には[食べ物|たべもの]が[豊富|ほうふ]にあり、[高|たか]いビルや[公園|こうえん]の[木|き]は[巣|す]を[作|つく]るのに[都合|つごう]がよい。つまり、カラスは[人間|にんげん]が[作り出|つくりだ]した[環境|かんきょう]にうまく[適応|てきおう]した[結果|けっか]、[私|わたし]たちの[身近|みぢか]に[住|す]むようになったのである。",
  "最近では、ごみ置き場にネットをかけたり、ごみを出す時間を守るよう呼びかけたりする地域が増えている。こうした取り組みによって食べ物が手に入りにくくなると、カラスの数は自然と減っていくという。カラスを追い払うより、カラスが集まる原因を減らすことのほうが効果的なのだ。": "[最近|さいきん]では、ごみ[置き場|おきば]にネットをかけたり、ごみを[出|だ]す[時間|じかん]を[守|まも]るよう[呼|よ]びかけたりする[地域|ちいき]が[増|ふ]えている。こうした[取り組|とりく]みによって[食べ物|たべもの]が[手|て]に[入|はい]りにくくなると、カラスの[数|かず]は[自然|しぜん]と[減|へ]っていくという。カラスを[追い払|おいはら]うより、カラスが[集|あつ]まる[原因|げんいん]を[減|へ]らすことのほうが[効果|こうか][的|てき]なのだ。",
  "嫌われ者のカラスだが、彼らが増えた背景には私たち人間の生活がある。カラスの問題を考えることは、自分たちの暮らし方を見直すことにもつながるのではないだろうか。": "[嫌|きら]われ[者|しゃ]のカラスだが、[彼|かれ]らが[増|ふ]えた[背景|はいけい]には[私|わたし]たち[人間|にんげん]の[生活|せいかつ]がある。カラスの[問題|もんだい]を[考|かんが]えることは、[自分|じぶん]たちの[暮|く]らし[方|かた]を[見直|みなお]すことにもつながるのではないだろうか。",
  "カラスの頭の良さを示す例として、本文にあるものはどれか。": "カラスの[頭|あたま]の[良|よ]さを[示|しめ]す[例|れい]として、[本文|ほんぶん]にあるものはどれか。",
  "人の顔を見分けることができる": "[人|ひと]の[顔|かお]を[見分|みわ]けることができる",
