  "眠りと記憶": "[眠|ねむ]りと[記憶|きおく]",
  "試験の前の晩、眠る時間を削って勉強した経験がある人は多いだろう。少しでも長く勉強したほうが、たくさん覚えられるような気がするからだ。ところが、最近の研究によると、こうした方法は必ずしも効果的ではないらしい。": "[試験|しけん]の[前|まえ]の[晩|ばん]、[眠|ねむ]る[時間|じかん]を[削|けず]って[勉強|べんきょう]した[経験|けいけん]がある[人|ひと]は[多|おお]いだろう。[少|すこ]しでも[長|なが]く[勉強|べんきょう]したほうが、たくさん[覚|おぼ]えられるような[気|き]がするからだ。ところが、[最近|さいきん]の[研究|けんきゅう]によると、こうした[方法|ほうほう]は[必|かなら]ずしも[効果|こうか][的|てき]ではないらしい。",
  "私たちが眠っている間、脳は休んでいるわけではない。昼間に経験したことや学んだことを整理し、必要な情報を長く覚えておけるように保存しているのである。ある実験では、単語を覚えた後に十分に眠ったグループのほうが、眠らずに過ごしたグループよりも、翌日のテストで良い成績を取ったという結果が出ている。": "[私|わたし]たちが[眠|ねむ]っている[間|ま]、[脳|のう]は[休|やす]んでいるわけではない。[昼間|ひるま]に[経験|けいけん]したことや[学|まな]んだことを[整理|せいり]し、[必要|ひつよう]な[情報|じょうほう]を[長|なが]く[覚|おぼ]えておけるように[保存|ほぞん]しているのである。ある[実験|じっけん]では、[単語|たんご]を[覚|おぼ]えた[後|のち]に[十分|じゅうぶん]に[眠|ねむ]ったグループのほうが、[眠|ねむ]らずに[過|す]ごしたグループよりも、[翌日|よくじつ]のテストで[良|よ]い[成績|せいせき]を[取|と]ったという[結果|けっか]が[出|で]ている。",
  "また、睡眠には、新しい考えを生み出す働きもあるとされている。解けなかった問題の答えが、一晩寝た後にふと思いつくことがあるのは、眠っている間に脳が情報を結びつけ直しているためだと考えられている。「難しいことは一晩寝てから決めよ」という言葉があるが、これにはどうやら科学的な根拠があるようだ。": "また、[睡眠|すいみん]には、[新|あたら]しい[考|かんが]えを[生み出|うみだ]す[働|はたら]きもあるとされている。[解|と]けなかった[問題|もんだい]の[答|こた]えが、[一|いち][晩|ばん][寝|ね]た[後|のち]にふと[思|おも]いつくことがあるのは、[眠|ねむ]っている[間|ま]に[脳|のう]が[情報|じょうほう]を[結|むす]びつけ[直|なお]しているためだと[考|かんが]えられている。「[難|むずか]しいことは[一|いち][晩|ばん][寝|ね]てから[決|き]めよ」という[言葉|ことば]があるが、これにはどうやら[科学|かがく][的|てき]な[根拠|こんきょ]があるようだ。",
  "もっとも、ただ長く眠ればよいというものではない。寝る直前までスマートフォンの画面を見ていると、脳が興奮して眠りが浅くなってしまう。毎日同じ時刻に寝起きし、寝る前は明るい光を避けるなど、睡眠の質を高める工夫が大切である。": "もっとも、ただ[長|なが]く[眠|ねむ]ればよいというものではない。[寝|ね]る[直前|ちょくぜん]までスマートフォンの[画面|がめん]を[見|み]ていると、[脳|のう]が[興奮|こうふん]して[眠|ねむ]りが[浅|あさ]くなってしまう。[毎日|まいにち][同|おな]じ[時刻|じこく]に[寝起|ねお]きし、[寝|ね]る[前|まえ]は[明|あか]るい[光|ひかり]を[避|さ]けるなど、[睡眠|すいみん]の[質|しつ]を[高|たか]める[工夫|くふう]が[大切|たいせつ]である。",
  "睡眠時間を減らして努力することは、一見まじめな態度に見える。しかし、本当に成果を上げたいのであれば、しっかり眠ることも学習の一部だと考えるべきだろう。": "[睡眠|すいみん][時間|じかん]を[減|へ]らして[努力|どりょく]することは、[一見|いっけん]まじめな[態度|たいど]に[見|み]える。しかし、[本当|ほんとう]に[成果|せいか]を[上|あ]げたいのであれば、しっかり[眠|ねむ]ることも[学習|がくしゅう]の[一部|いちぶ]だと[考|かんが]えるべきだろう。",
  "私たちが眠っている間、脳は何をしているか。": "[私|わたし]たちが[眠|ねむ]っている[間|ま]、[脳|のう]は[何|なに]をしているか。",
