  "眠らなかったグループのほうがテストの成績が良かった": "[眠|ねむ]らなかったグループのほうがテストの[成績|せいせき]が[良|よ]かった",
  "二つのグループの成績はほとんど同じだった": "[二|ふた]つのグループの[成績|せいせき]はほとんど[同|おな]じだった",
  "長く眠りすぎたグループは成績が悪かった": "[長|なが]く[眠|ねむ]りすぎたグループは[成績|せいせき]が[悪|わる]かった",
  "睡眠の質を高める工夫として、本文の内容に合うものはどれか。": "[睡眠|すいみん]の[質|しつ]を[高|たか]める[工夫|くふう]として、[本文|ほんぶん]の[内容|ないよう]に[合|あ]うものはどれか。",
  "寝る前は明るい光を避ける": "[寝|ね]る[前|まえ]は[明|あか]るい[光|ひかり]を[避|さ]ける",
  "寝る直前までスマートフォンを見る": "[寝|ね]る[直前|ちょくぜん]までスマートフォンを[見|み]る",
  "休みの日にまとめて長く寝る": "[休|やす]みの[日|ひ]にまとめて[長|なが]く[寝|ね]る",
  "寝る前に熱いお茶を飲む": "[寝|ね]る[前|まえ]に[熱|あつ]いお[茶|ちゃ]を[飲|の]む",
  "雪の朝の足跡": "[雪|ゆき]の[朝|あさ]の[足跡|あしあと]",
  "ある冬の朝、探偵の森川は古い友人の山本から電話を受けた。山本が経営する小さな旅館で、客から預かっていた高価な腕時計がなくなったというのだ。森川が急いで旅館に向かうと、辺りは前の晩から降り続いた雪で真っ白になっていた。": "ある[冬|ふゆ]の[朝|あさ]、[探偵|たんてい]の[森川|もりかわ]は[古|ふる]い[友人|ゆうじん]の[山本|やまもと]から[電話|でんわ]を[受|う]けた。[山本|やまもと]が[経営|けいえい]する[小|ちい]さな[旅館|りょかん]で、[客|きゃく]から[預|あず]かっていた[高価|こうか]な[腕|うで][時計|とけい]がなくなったというのだ。[森川|もりかわ]が[急|いそ]いで[旅館|りょかん]に[向|む]かうと、[辺|あた]りは[前|まえ]の[晩|ばん]から[降り続|ふりつづ]いた[雪|ゆき]で[真っ白|まっしろ]になっていた。",
  "山本の話によると、腕時計は夜十時に帳場の引き出しにしまわれた。従業員の佐藤は十一時まで帳場にいたが、その間は誰も近づかなかったという。佐藤が自分の部屋に戻った後、朝六時に山本が確認すると、腕時計は消えていた。なお、雪は夜十一時ごろにやんだそうだ。": "[山本|やまもと]の[話|はなし]によると、[腕|うで][時計|とけい]は[夜|よる][十時|じゅうじ]に[帳場|ちょうば]の[引き出|ひきだ]しにしまわれた。[従業|じゅうぎょう][員|いん]の[佐藤|さとう]は[十一時|じゅういちじ]まで[帳場|ちょうば]にいたが、その[間|かん]は[誰|だれ]も[近|ちか]づかなかったという。[佐藤|さとう]が[自分|じぶん]の[部屋|へや]に[戻|もど]った[後|のち]、[朝|あさ][六時|ろくじ]に[山本|やまもと]が[確認|かくにん]すると、[腕|うで][時計|とけい]は[消|き]えていた。なお、[雪|ゆき]は[夜|よる][十一時|じゅういちじ]ごろにやんだそうだ。",
  "その夜旅館にいたのは、佐藤のほかに、宿泊客の田中と料理人の木村だった。田中は「十時には寝ていて、朝まで一度も部屋を出なかった」と話した。木村は「仕事を終えて、十時半ごろ歩いて家に帰った。雪が強くて大変だった」と答えた。森川が外に出てみると、旅館の裏口から木村の家の方向へ、一筋の足跡がはっきりと残っていた。": "その[夜|よる][旅館|りょかん]にいたのは、[佐藤|さとう]のほかに、[宿泊|しゅくはく][客|きゃく]の[田中|たなか]と[料理|りょうり][人|じん]の[木村|きむら]だった。[田中|たなか]は「[十時|じゅうじ]には[寝|ね]ていて、[朝|あさ]まで[一度|いちど]も[部屋|へや]を[出|で]なかった」と[話|はな]した。[木村|きむら]は「[仕事|しごと]を[終|お]えて、[十時|じゅうじ][半|はん]ごろ[歩|ある]いて[家|いえ]に[帰|かえ]った。[雪|ゆき]が[強|つよ]くて[大変|たいへん]だった」と[答|こた]えた。[森川|もりかわ]が[外|そと]に[出|で]てみると、[旅館|りょかん]の[裏口|うらぐち]から[木村|きむら]の[家|いえ]の[方向|ほうこう]へ、[一筋|ひとすじ]の[足跡|あしあと]がはっきりと[残|のこ]っていた。",
  "森川はしばらく足跡を見つめた後、静かに言った。「木村さん、あなたが帰ったのは十時半ではありませんね。雪は十一時までやまなかった。もし十時半に出たのなら、足跡はその後に降った雪で消えているか、少なくともぼやけているはずです。これほどくっきり残っているのは、雪がやんだ後に歩いた証拠です。」": "[森川|もりかわ]はしばらく[足跡|あしあと]を[見|み]つめた[後|のち]、[静|しず]かに[言|い]った。「[木村|きむら]さん、あなたが[帰|かえ]ったのは[十時|じゅうじ][半|はん]ではありませんね。[雪|ゆき]は[十一時|じゅういちじ]までやまなかった。もし[十時|じゅうじ][半|はん]に[出|で]たのなら、[足跡|あしあと]はその[後|ご]に[降|ふ]った[雪|ゆき]で[消|き]えているか、[少|すく]なくともぼやけているはずです。これほどくっきり[残|のこ]っているのは、[雪|ゆき]がやんだ[後|のち]に[歩|ある]いた[証拠|しょうこ]です。」",
  "木村の顔は真っ青になった。彼は佐藤が帳場を離れるのを待って腕時計を盗み、それから家に帰ったのだった。腕時計は木村の鞄の中から見つかり、無事に客のもとへ戻された。": "[木村|きむら]の[顔|かお]は[真っ青|まっさお]になった。[彼|かれ]は[佐藤|さとう]が[帳場|ちょうば]を[離|はな]れるのを[待|ま]って[腕|うで][時計|とけい]を[盗|ぬす]み、それから[家|いえ]に[帰|かえ]ったのだった。[腕|うで][時計|とけい]は[木村|きむら]の[鞄|かばん]の[中|なか]から[見|み]つかり、[無事|ぶじ]に[客|きゃく]のもとへ[戻|もど]された。",
  "腕時計が盗まれたのは、いつごろだと考えられるか。": "[腕|うで][時計|とけい]が[盗|ぬす]まれたのは、いつごろだと[考|かんが]えられるか。",
