  "森川が木村をうそをついていると考えた手がかりは何か。": "[森川|もりかわ]が[木村|きむら]をうそをついていると[考|かんが]えた[手|て]がかりは[何|なに]か。",
  "雪の上の足跡がくっきり残っていたこと": "[雪|ゆき]の[上|うえ]の[足跡|あしあと]がくっきり[残|のこ]っていたこと",
