  "手紙を書くということ": "[手紙|てがみ]を[書|か]くということ",
  "先日、引っ越しの準備をしていたら、押し入れの奥から古い箱が出てきた。中には、学生時代に友人や家族からもらった手紙がぎっしり詰まっていた。懐かしさのあまり、片付けの手を止めて一通ずつ読み返しているうちに、気がつくと外は暗くなっていた。": "[先日|せんじつ]、[引っ越|ひっこ]しの[準備|じゅんび]をしていたら、[押し入|おしい]れの[奥|おく]から[古|ふる]い[箱|はこ]が[出|で]てきた。[中|なか]には、[学生|がくせい][時代|じだい]に[友人|ゆうじん]や[家族|かぞく]からもらった[手紙|てがみ]がぎっしり[詰|つ]まっていた。[懐|なつ]かしさのあまり、[片付|かたづ]けの[手|て]を[止|と]めて[一|いち][通|つう]ずつ[読み返|よみかえ]しているうちに、[気|き]がつくと[外|そと]は[暗|くら]くなっていた。",
  "今では、連絡を取るのはほとんどメールやメッセージアプリである。思いついたときにすぐ送れて、相手もすぐに返事をくれる。便利であることは間違いない。しかし、何年もたってから読み返したくなるようなメッセージが、果たしてどれほどあるだろうか。": "[今|いま]では、[連絡|れんらく]を[取|と]るのはほとんどメールやメッセージアプリである。[思|おも]いついたときにすぐ[送|おく]れて、[相手|あいて]もすぐに[返事|へんじ]をくれる。[便利|べんり]であることは[間違|まちが]いない。しかし、[何|なん][年|ねん]もたってから[読み返|よみかえ]したくなるようなメッセージが、[果|は]たしてどれほどあるだろうか。",
  "手紙には、文字以外にもさまざまな情報が含まれている。丁寧に書かれた字からは相手の気持ちが伝わってくるし、書き直した跡からは、言葉を選ぶのに迷った様子がうかがえる。便箋や切手の選び方にも、その人らしさが表れる。手紙を受け取るということは、相手がかけてくれた時間と手間を受け取ることなのだと思う。": "[手紙|てがみ]には、[文字|もじ][以外|いがい]にもさまざまな[情報|じょうほう]が[含|ふく]まれている。[丁寧|ていねい]に[書|か]かれた[字|じ]からは[相手|あいて]の[気持|きも]ちが[伝|つた]わってくるし、[書き直|かきなお]した[跡|あと]からは、[言葉|ことば]を[選|えら]ぶのに[迷|まよ]った[様子|ようす]がうかがえる。[便箋|びんせん]や[切手|きって]の[選び方|えらびかた]にも、その[人|ひと]らしさが[表|あらわ]れる。[手紙|てがみ]を[受け取|うけと]るということは、[相手|あいて]がかけてくれた[時間|じかん]と[手間|てま]を[受け取|うけと]ることなのだと[思|おも]う。",
  "そこで私は、久しぶりに手紙を書いてみることにした。宛先は、長い間会っていない大学時代の友人だ。いざペンを持つと、何を書けばいいのか迷ってしまい、一枚書き上げるのに一時間近くかかった。それでも、相手の顔を思い浮かべながら言葉を選ぶ時間は、不思議と心が落ち着くものだった。": "そこで[私|わたし]は、[久|ひさ]しぶりに[手紙|てがみ]を[書|か]いてみることにした。[宛先|あてさき]は、[長|なが]い[間|あいだ][会|あ]っていない[大学|だいがく][時代|じだい]の[友人|ゆうじん]だ。いざペンを[持|も]つと、[何|なに]を[書|か]けばいいのか[迷|まよ]ってしまい、[一|いち][枚|まい][書き上|かきあ]げるのに[一時間|いちじかん][近|ちか]くかかった。それでも、[相手|あいて]の[顔|かお]を[思い浮|おもいう]かべながら[言葉|ことば]を[選|えら]ぶ[時間|じかん]は、[不思議|ふしぎ]と[心|こころ]が[落ち着|おちつ]くものだった。",
  "一週間後、友人から返事が届いた。封筒を開けたときのうれしさは、メールでは決して味わえないものだった。便利さだけでは得られない価値が、手紙にはあるのだろう。": "[一週間|いっしゅうかん][後|ご]、[友人|ゆうじん]から[返事|へんじ]が[届|とど]いた。[封筒|ふうとう]を[開|あ]けたときのうれしさは、メールでは[決|けっ]して[味|あじ]わえないものだった。[便利|べんり]さだけでは[得|え]られない[価値|かち]が、[手紙|てがみ]にはあるのだろう。",
  "筆者が古い手紙を見つけたのは、どんなときか。": "[筆者|ひっしゃ]が[古|ふる]い[手紙|てがみ]を[見|み]つけたのは、どんなときか。",
