  "和菓子と季節": "[和菓子|わがし]と[季節|きせつ]",
  "和菓子屋の店先をのぞくと、季節によって並んでいる菓子が変わることに気づく。春には桜の花をかたどった菓子、夏には涼しげな透明の菓子、秋には栗や柿を使った菓子が並ぶ。和菓子は、味だけでなく見た目でも季節を表現しているのである。": "[和菓子|わがし][屋|や]の[店先|みせさき]をのぞくと、[季節|きせつ]によって[並|なら]んでいる[菓子|かし]が[変|か]わることに[気|き]づく。[春|はる]には[桜|さくら]の[花|はな]をかたどった[菓子|かし]、[夏|なつ]には[涼|すず]しげな[透明|とうめい]の[菓子|かし]、[秋|あき]には[栗|くり]や[柿|かき]を[使|つか]った[菓子|かし]が[並|なら]ぶ。[和菓子|わがし]は、[味|あじ]だけでなく[見た目|みため]でも[季節|きせつ]を[表現|ひょうげん]しているのである。",
  "こうした和菓子の多くには、美しい名前がつけられている。たとえば、同じような丸い形の菓子でも、色や模様によって「初雪」「春の野」などと呼び分けられる。名前を聞いた客は、菓子の形と言葉を重ね合わせて、その風景を想像する。いわば、食べる前から楽しみが始まっているわけだ。": "こうした[和菓子|わがし]の[多|おお]くには、[美|うつく]しい[名前|なまえ]がつけられている。たとえば、[同|おな]じような[丸|まる]い[形|かたち]の[菓子|かし]でも、[色|いろ]や[模様|もよう]によって「[初雪|はつゆき]」「[春|はる]の[野|の]」などと[呼|よ]び[分|わ]けられる。[名前|なまえ]を[聞|き]いた[客|きゃく]は、[菓子|かし]の[形|かたち]と[言葉|ことば]を[重ね合|かさねあ]わせて、その[風景|ふうけい]を[想像|そうぞう]する。いわば、[食|た]べる[前|まえ]から[楽|たの]しみが[始|はじ]まっているわけだ。",
  "和菓子が季節を大切にするのは、茶道との関わりが深いからだと言われている。茶会では、季節に合わせて道具や掛け軸を選び、客をもてなす。その中で出される菓子も、季節の雰囲気を伝える大切な役割を担ってきた。職人たちは、限られた材料で四季の移り変わりを表そうと、工夫を重ねてきたのである。": "[和菓子|わがし]が[季節|きせつ]を[大切|たいせつ]にするのは、[茶道|さどう]との[関|かか]わりが[深|ふか]いからだと[言|い]われている。[茶会|ちゃかい]では、[季節|きせつ]に[合|あ]わせて[道具|どうぐ]や[掛け軸|かけじく]を[選|えら]び、[客|きゃく]をもてなす。その[中|なか]で[出|だ]される[菓子|かし]も、[季節|きせつ]の[雰囲気|ふんいき]を[伝|つた]える[大切|たいせつ]な[役割|やくわり]を[担|にな]ってきた。[職人|しょくにん]たちは、[限|かぎ]られた[材料|ざいりょう]で[四季|しき]の[移り変|うつりか]わりを[表|あらわ]そうと、[工夫|くふう]を[重|かさ]ねてきたのである。",
  "ところが、生活の洋風化が進むにつれて、和菓子を日常的に食べる人は減っている。若い世代の中には、洋菓子のほうが身近だという人も多いだろう。それでも最近は、和菓子作りの体験教室が外国人観光客に人気を集めるなど、新しい形で注目されることも増えてきた。": "ところが、[生活|せいかつ]の[洋風|ようふう][化|か]が[進|すす]むにつれて、[和菓子|わがし]を[日常|にちじょう][的|てき]に[食|た]べる[人|ひと]は[減|へ]っている。[若|わか]い[世代|せだい]の[中|なか]には、[洋菓子|ようがし]のほうが[身近|みぢか]だという[人|ひと]も[多|おお]いだろう。それでも[最近|さいきん]は、[和菓子|わがし][作|づく]りの[体験|たいけん][教室|きょうしつ]が[外国|がいこく][人|じん][観光|かんこう][客|きゃく]に[人気|にんき]を[集|あつ]めるなど、[新|あたら]しい[形|かたち]で[注目|ちゅうもく]されることも[増|ふ]えてきた。",
  "季節を目で味わうという楽しみ方は、和菓子ならではのものだ。忙しい毎日の中でも、たまには和菓子を一つ買って、季節の移り変わりを感じてみてはどうだろうか。": "[季節|きせつ]を[目|め]で[味|あじ]わうという[楽|たの]しみ[方|かた]は、[和菓子|わがし]ならではのものだ。[忙|いそが]しい[毎日|まいにち]の[中|なか]でも、たまには[和菓子|わがし]を[一|ひと]つ[買|か]って、[季節|きせつ]の[移り変|うつりか]わりを[感|かん]じてみてはどうだろうか。",
  "和菓子の名前について、本文の内容に合うものはどれか。": "[和菓子|わがし]の[名前|なまえ]について、[本文|ほんぶん]の[内容|ないよう]に[合|あ]うものはどれか。",
  "同じような形でも、色や模様によって名前が変わる": "[同|おな]じような[形|かたち]でも、[色|いろ]や[模様|もよう]によって[名前|なまえ]が[変|か]わる",
