  "材料の名前がそのまま使われている": "[材料|ざいりょう]の[名前|なまえ]がそのまま[使|つか]われている",
  "名前は客が自由に決めることができる": "[名前|なまえ]は[客|きゃく]が[自由|じゆう]に[決|き]めることができる",
  "和菓子が季節を大切にする理由として、本文で挙げられているものは何か。": "[和菓子|わがし]が[季節|きせつ]を[大切|たいせつ]にする[理由|りゆう]として、[本文|ほんぶん]で[挙|あ]げられているものは[何|なに]か。",
  "茶道との関わりが深いから": "[茶道|さどう]との[関|かか]わりが[深|ふか]いから",
  "季節によって材料の値段が変わるから": "[季節|きせつ]によって[材料|ざいりょう]の[値段|ねだん]が[変|か]わるから",
  "外国人観光客に人気があるから": "[外国|がいこく][人|じん][観光|かんこう][客|きゃく]に[人気|にんき]があるから",
  "洋菓子と区別するため": "[洋菓子|ようがし]と[区別|くべつ]するため",
  "最近の和菓子について、本文で述べられていることはどれか。": "[最近|さいきん]の[和菓子|わがし]について、[本文|ほんぶん]で[述|の]べられていることはどれか。",
  "和菓子作りの体験教室が外国人観光客に人気だ": "[和菓子|わがし][作|づく]りの[体験|たいけん][教室|きょうしつ]が[外国|がいこく][人|じん][観光|かんこう][客|きゃく]に[人気|にんき]だ",
  "若い世代が洋菓子より和菓子を好むようになった": "[若|わか]い[世代|せだい]が[洋菓子|ようがし]より[和菓子|わがし]を[好|この]むようになった",
  "和菓子を日常的に食べる人が増えている": "[和菓子|わがし]を[日常|にちじょう][的|てき]に[食|た]べる[人|ひと]が[増|ふ]えている",
  "和菓子屋の数が大きく増えている": "[和菓子|わがし][屋|や]の[数|かず]が[大|おお]きく[増|ふ]えている",
  "空き家が語るもの": "[空き家|あきや]が[語|かた]るもの",
  "地方を旅していると、雨戸が閉まったままの家や、庭に草が生い茂った家を見かけることが多い。持ち主が亡くなったり、都会に引っ越したりして、誰も住まなくなった「空き家」である。日本では空き家の数が年々増え続けており、大きな社会問題となっている。": "[地方|ちほう]を[旅|たび]していると、[雨戸|あまど]が[閉|し]まったままの[家|いえ]や、[庭|にわ]に[草|くさ]が[生い茂|おいしげ]った[家|いえ]を[見|み]かけることが[多|おお]い。[持ち主|もちぬし]が[亡|な]くなったり、[都会|とかい]に[引っ越|ひっこ]したりして、[誰|だれ]も[住|す]まなくなった「[空き家|あきや]」である。[日本|にほん]では[空き家|あきや]の[数|かず]が[年々|ねんねん][増|ふ]え[続|つづ]けており、[大|おお]きな[社会|しゃかい][問題|もんだい]となっている。",
  "空き家が増える背景には、人口の減少と高齢化がある。地方では若者が仕事を求めて都会へ出ていき、残された親の世代が亡くなると、家を引き継ぐ人がいなくなってしまう。また、古い家を壊すには多額の費用がかかるため、そのまま放置されるケースも少なくない。": "[空き家|あきや]が[増|ふ]える[背景|はいけい]には、[人口|じんこう]の[減少|げんしょう]と[高齢|こうれい][化|か]がある。[地方|ちほう]では[若者|わかもの]が[仕事|しごと]を[求|もと]めて[都会|とかい]へ[出|で]ていき、[残|のこ]された[親|おや]の[世代|せだい]が[亡|な]くなると、[家|いえ]を[引き継|ひきつ]ぐ[人|ひと]がいなくなってしまう。また、[古|ふる]い[家|いえ]を[壊|こわ]すには[多額|たがく]の[費用|ひよう]がかかるため、そのまま[放置|ほうち]されるケースも[少|すく]なくない。",
  "人が住まなくなった家は、想像以上に早く傷んでいく。屋根や壁が壊れて周囲の住民に危険を及ぼしたり、ごみが捨てられたりすることもある。さらに、空き家が並ぶ地域は活気を失い、ますます人が住みたがらなくなるという悪循環に陥りかねない。": "[人|ひと]が[住|す]まなくなった[家|いえ]は、[想像|そうぞう][以上|いじょう]に[早|はや]く[傷|いた]んでいく。[屋根|やね]や[壁|かべ]が[壊|こわ]れて[周囲|しゅうい]の[住民|じゅうみん]に[危険|きけん]を[及|およ]ぼしたり、ごみが[捨|す]てられたりすることもある。さらに、[空き家|あきや]が[並|なら]ぶ[地域|ちいき]は[活気|かっき]を[失|うしな]い、ますます[人|ひと]が[住|す]みたがらなくなるという[悪循環|あくじゅんかん]に[陥|おちい]りかねない。",
  "一方で、空き家を地域の資源として生かそうとする動きも出てきている。古い家を改装してカフェや宿泊施設にしたり、都会から移り住みたい人に安く貸し出したりする試みだ。ある町では、空き家を利用した移住者向けの住宅が評判を呼び、若い家族が少しずつ増え始めているという。": "[一方|いっぽう]で、[空き家|あきや]を[地域|ちいき]の[資源|しげん]として[生|い]かそうとする[動|うご]きも[出|で]てきている。[古|ふる]い[家|いえ]を[改装|かいそう]してカフェや[宿泊|しゅくはく][施設|しせつ]にしたり、[都会|とかい]から[移り住|うつりす]みたい[人|ひと]に[安|やす]く[貸し出|かしだ]したりする[試|こころ]みだ。ある[町|まち]では、[空き家|あきや]を[利用|りよう]した[移住|いじゅう][者|しゃ][向|む]けの[住宅|じゅうたく]が[評判|ひょうばん]を[呼|よ]び、[若|わか]い[家族|かぞく]が[少|すこ]しずつ[増|ふ]え[始|はじ]めているという。",
  "空き家は、放っておけば地域の負担になるが、使い方次第で町を元気にする力にもなる。古い家に新しい役割を与えることができるかどうかは、そこに住む人々の知恵にかかっているのではないだろうか。": "[空き家|あきや]は、[放|はな]っておけば[地域|ちいき]の[負担|ふたん]になるが、[使い方|つかいかた][次第|しだい]で[町|まち]を[元気|げんき]にする[力|ちから]にもなる。[古|ふる]い[家|いえ]に[新|あたら]しい[役割|やくわり]を[与|あた]えることができるかどうかは、そこに[住|す]む[人々|ひとびと]の[知恵|ちえ]にかかっているのではないだろうか。",
  "空き家が増える理由として、本文に書かれていないものはどれか。": "[空き家|あきや]が[増|ふ]える[理由|りゆう]として、[本文|ほんぶん]に[書|か]かれていないものはどれか。",
  "家にかかる税金が高くなったこと": "[家|いえ]にかかる[税金|ぜいきん]が[高|たか]くなったこと",
