  "空き家は使い方次第で町を元気にする力になる": "[空き家|あきや]は[使い方|つかいかた][次第|しだい]で[町|まち]を[元気|げんき]にする[力|ちから]になる",
  "空き家はすべてできるだけ早く壊すべきだ": "[空き家|あきや]はすべてできるだけ[早|はや]く[壊|こわ]すべきだ",
  "空き家の問題は国にしか解決できない": "[空き家|あきや]の[問題|もんだい]は[国|くに]にしか[解決|かいけつ]できない",
  "空き家は都会にはまったく関係のない問題だ": "[空き家|あきや]は[都会|とかい]にはまったく[関係|かんけい]のない[問題|もんだい]だ",
  "雑草のしたたかな生き方": "[雑草|ざっそう]のしたたかな[生き方|いきかた]",
  "道路のひび割れや駐車場のすみなど、ほんのわずかな土しかない場所にも、雑草は元気に生えている。抜いても抜いてもすぐに生えてくるため、庭の手入れをする人にとっては悩みの種だ。しかし、植物の立場から見ると、雑草は驚くほど巧みな生き方をしている。": "[道路|どうろ]のひび[割|わ]れや[駐車|ちゅうしゃ][場|じょう]のすみなど、ほんのわずかな[土|ど]しかない[場所|ばしょ]にも、[雑草|ざっそう]は[元気|げんき]に[生|は]えている。[抜|ぬ]いても[抜|ぬ]いてもすぐに[生|は]えてくるため、[庭|にわ]の[手入|てい]れをする[人|ひと]にとっては[悩|なや]みの[種|たね]だ。しかし、[植物|しょくぶつ]の[立場|たちば]から[見|み]ると、[雑草|ざっそう]は[驚|おどろ]くほど[巧|たく]みな[生き方|いきかた]をしている。",
  "意外なことに、雑草は実は競争に弱い植物だと言われている。森や草原のように多くの植物が育つ場所では、背の高い植物に光をさえぎられ、生き残ることが難しい。そこで雑草は、他の植物が育ちにくい場所、つまり人に踏まれたり、草刈りをされたりする場所を選んで生きるようになったのである。": "[意外|いがい]なことに、[雑草|ざっそう]は[実|じつ]は[競争|きょうそう]に[弱|よわ]い[植物|しょくぶつ]だと[言|い]われている。[森|もり]や[草原|そうげん]のように[多|おお]くの[植物|しょくぶつ]が[育|そだ]つ[場所|ばしょ]では、[背|せ]の[高|たか]い[植物|しょくぶつ]に[光|ひかり]をさえぎられ、[生き残|いきのこ]ることが[難|むずか]しい。そこで[雑草|ざっそう]は、[他|た]の[植物|しょくぶつ]が[育|そだ]ちにくい[場所|ばしょ]、つまり[人|じん]に[踏|ふ]まれたり、[草刈|くさか]りをされたりする[場所|ばしょ]を[選|えら]んで[生|い]きるようになったのである。",
  "例えば、道によく生えているオオバコという草は、踏まれることに強い。葉や茎がやわらかく、踏まれても折れにくいうえ、種は濡れるとねばねばして、人の靴や車のタイヤにくっつく。つまり、踏まれることを利用して、種を遠くまで運んでもらっているのだ。": "[例|たと]えば、[道|みち]によく[生|は]えているオオバコという[草|くさ]は、[踏|ふ]まれることに[強|つよ]い。[葉|は]や[茎|くき]がやわらかく、[踏|ふ]まれても[折|お]れにくいうえ、[種|たね]は[濡|ぬ]れるとねばねばして、[人|ひと]の[靴|くつ]や[車|くるま]のタイヤにくっつく。つまり、[踏|ふ]まれることを[利用|りよう]して、[種|たね]を[遠|とお]くまで[運|はこ]んでもらっているのだ。",
  "また、多くの雑草は一度にすべての種を芽生えさせるのではなく、時期をずらして少しずつ芽を出す。そのため、一度草を抜いても、土の中に残った種が次々と芽を出してくる。環境の変化に備えて、危険を分散しているわけである。": "また、[多|おお]くの[雑草|ざっそう]は[一度|いちど]にすべての[種|たね]を[芽生|めば]えさせるのではなく、[時期|じき]をずらして[少|すこ]しずつ[芽|め]を[出|だ]す。そのため、[一度|いちど][草|くさ]を[抜|ぬ]いても、[土|ど]の[中|なか]に[残|のこ]った[種|たね]が[次々|つぎつぎ]と[芽|め]を[出|だ]してくる。[環境|かんきょう]の[変化|へんか]に[備|そな]えて、[危険|きけん]を[分散|ぶんさん]しているわけである。",
  "弱いからこそ、強い者が来ない場所で工夫して生きる。雑草のこうした生き方には、私たち人間が学ぶべき点も多いのではないだろうか。": "[弱|よわ]いからこそ、[強|つよ]い[者|もの]が[来|こ]ない[場所|ばしょ]で[工夫|くふう]して[生|い]きる。[雑草|ざっそう]のこうした[生き方|いきかた]には、[私|わたし]たち[人間|にんげん]が[学|まな]ぶべき[点|てん]も[多|おお]いのではないだろうか。",
  "筆者によると、雑草が道や駐車場に生えているのはなぜか。": "[筆者|ひっしゃ]によると、[雑草|ざっそう]が[道|みち]や[駐車|ちゅうしゃ][場|じょう]に[生|は]えているのはなぜか。",
  "競争に弱く、他の植物が育ちにくい場所を選んだから": "[競争|きょうそう]に[弱|よわ]く、[他|た]の[植物|しょくぶつ]が[育|そだ]ちにくい[場所|ばしょ]を[選|えら]んだから",
