  "オオバコについて、本文の内容に合うものはどれか。": "オオバコについて、[本文|ほんぶん]の[内容|ないよう]に[合|あ]うものはどれか。",
  "踏まれることを利用して種を運んでもらう": "[踏|ふ]まれることを[利用|りよう]して[種|たね]を[運|はこ]んでもらう",
  "背が高く、他の植物の光をさえぎる": "[背|せ]が[高|たか]く、[他|た]の[植物|しょくぶつ]の[光|ひかり]をさえぎる",
  "種は乾くとねばねばする": "[種|たね]は[乾|かわ]くとねばねばする",
  "踏まれるとすぐに枯れてしまう": "[踏|ふ]まれるとすぐに[枯|か]れてしまう",
  "雑草が時期をずらして芽を出すのはなぜか。": "[雑草|ざっそう]が[時期|じき]をずらして[芽|め]を[出|だ]すのはなぜか。",
  "環境の変化に備えて危険を分散するため": "[環境|かんきょう]の[変化|へんか]に[備|そな]えて[危険|きけん]を[分散|ぶんさん]するため",
  "ほかの雑草より早く大きくなるため": "ほかの[雑草|ざっそう]より[早|はや]く[大|おお]きくなるため",
  "種の数を少しでも減らすため": "[種|たね]の[数|かず]を[少|すこ]しでも[減|へ]らすため",
  "人に見つからないようにするため": "[人|ひと]に[見|み]つからないようにするため",
  "雨の日の三本の傘": "[雨|あめ]の[日|ひ]の[三本|さんぼん]の[傘|かさ]",
  "激しい雨が降る午後、探偵の森川のもとに、資産家の大野から依頼があった。書斎の机に置いていた大切な契約書がなくなったというのだ。大野は二時から三時まで昼寝をしていて、その間に何者かが書斎に入ったらしい。森川が大野の家に着いたのは、四時少し前のことだった。": "[激|はげ]しい[雨|あめ]が[降|ふ]る[午後|ごご]、[探偵|たんてい]の[森川|もりかわ]のもとに、[資産|しさん][家|か]の[大野|おおの]から[依頼|いらい]があった。[書斎|しょさい]の[机|つくえ]に[置|お]いていた[大切|たいせつ]な[契約|けいやく][書|しょ]がなくなったというのだ。[大野|おおの]は[二時|にじ]から[三時|さんじ]まで[昼寝|ひるね]をしていて、その[間|かん]に[何者|なにもの]かが[書斎|しょさい]に[入|はい]ったらしい。[森川|もりかわ]が[大野|おおの]の[家|いえ]に[着|つ]いたのは、[四時|よじ][少|すこ]し[前|まえ]のことだった。",
  "その日、大野の家を訪れたのは三人だった。甥の健太は「僕が来たのは三時半です。叔父さんが起きた後ですよ」と言った。秘書の松井は「私は一時に来て、ずっと台所で書類の整理をしていました」と答えた。近所の医者の石田は「三時四十分ごろ、診察に来たばかりです」と話した。": "その[日|ひ]、[大野|おおの]の[家|いえ]を[訪|おとず]れたのは[三人|さんにん]だった。[甥|おい]の[健太|けんた]は「[僕|ぼく]が[来|き]たのは[三時|さんじ][半|はん]です。[叔父|おじ]さんが[起|お]きた[後|のち]ですよ」と[言|い]った。[秘書|ひしょ]の[松井|まつい]は「[私|わたし]は[一時|いちじ]に[来|き]て、ずっと[台所|だいどころ]で[書類|しょるい]の[整理|せいり]をしていました」と[答|こた]えた。[近所|きんじょ]の[医者|いしゃ]の[石田|いしだ]は「[三時|さんじ][四|よん][十|じゅう][分|ふん]ごろ、[診察|しんさつ]に[来|き]たばかりです」と[話|はな]した。",
  "森川は玄関に置かれた三本の傘を見た。松井の傘はすっかり乾いていた。石田の傘からは、まだ水が流れ落ちていた。ところが、健太の傘は少し湿っている程度で、ほとんど乾きかけていた。森川は大野に尋ねた。「雨はいつから降っていますか。」「昼過ぎからずっと、強く降り続けていますよ。」": "[森川|もりかわ]は[玄関|げんかん]に[置|お]かれた[三本|さんぼん]の[傘|かさ]を[見|み]た。[松井|まつい]の[傘|かさ]はすっかり[乾|かわ]いていた。[石田|いしだ]の[傘|かさ]からは、まだ[水|みず]が[流れ落|ながれお]ちていた。ところが、[健太|けんた]の[傘|かさ]は[少|すこ]し[湿|しめ]っている[程度|ていど]で、ほとんど[乾|かわ]きかけていた。[森川|もりかわ]は[大野|おおの]に[尋|たず]ねた。「[雨|あめ]はいつから[降|ふ]っていますか。」「[昼過|ひるす]ぎからずっと、[強|つよ]く[降|ふ]り[続|つづ]けていますよ。」",
  "森川は健太の方を向いた。「健太さん、あなたは三時半に来たと言いましたね。しかし、この強い雨の中を歩いてきたばかりなら、あなたの傘も石田先生の傘と同じように濡れているはずです。ほとんど乾いているということは、あなたはもっと前、おそらく叔父さんが昼寝をしていたころには、すでにこの家にいたのではありませんか。」": "[森川|もりかわ]は[健太|けんた]の[方|ほう]を[向|む]いた。「[健太|けんた]さん、あなたは[三時|さんじ][半|はん]に[来|き]たと[言|い]いましたね。しかし、この[強|つよ]い[雨|あめ]の[中|なか]を[歩|ある]いてきたばかりなら、あなたの[傘|かさ]も[石田|いしだ][先生|せんせい]の[傘|かさ]と[同|おな]じように[濡|ぬ]れているはずです。ほとんど[乾|かわ]いているということは、あなたはもっと[前|まえ]、おそらく[叔父|おじ]さんが[昼寝|ひるね]をしていたころには、すでにこの[家|いえ]にいたのではありませんか。」",
  "健太はしばらく黙っていたが、やがて契約書を鞄から取り出した。借金に困り、叔父の財産に関する書類を持ち出そうとしたのだという。大野は深いため息をついたが、警察には知らせず、もう一度甥とよく話し合うことにした。": "[健太|けんた]はしばらく[黙|だま]っていたが、やがて[契約|けいやく][書|しょ]を[鞄|かばん]から[取り出|とりだ]した。[借金|しゃっきん]に[困|こま]り、[叔父|おじ]の[財産|ざいさん]に[関|かん]する[書類|しょるい]を[持ち出|もちだ]そうとしたのだという。[大野|おおの]は[深|ふか]いため[息|いき]をついたが、[警察|けいさつ]には[知|し]らせず、もう[一度|いちど][甥|おい]とよく[話し合|はなしあ]うことにした。",
  "契約書が持ち出されたのは、いつだと考えられるか。": "[契約|けいやく][書|しょ]が[持ち出|もちだ]されたのは、いつだと[考|かんが]えられるか。",
