  "松井で、傘がすっかり乾いていたこと": "[松井|まつい]で、[傘|かさ]がすっかり[乾|かわ]いていたこと",
  "石田で、傘から水が流れ落ちていたこと": "[石田|いしだ]で、[傘|かさ]から[水|みず]が[流れ落|ながれお]ちていたこと",
  "大野で、昼寝をしていたと言ったこと": "[大野|おおの]で、[昼寝|ひるね]をしていたと[言|い]ったこと",
  "革のケースの中身": "[革|かわ]のケースの[中身|なかみ]",
  "大学で心理学を教える小林先生は、ちょっとした謎を解くのが得意なことで知られている。ある日の昼、先生は翌日のゼミで使う古いカメラを、茶色い革のケースに入れたまま教室の机に置いた。そして、そこにいた三人の学生に「大切な物だから、触らないように」と伝えて研究室に戻った。": "[大学|だいがく]で[心理|しんり][学|がく]を[教|おし]える[小林|こばやし][先生|せんせい]は、ちょっとした[謎|なぞ]を[解|と]くのが[得意|とくい]なことで[知|し]られている。ある[日|ひ]の[昼|ひる]、[先生|せんせい]は[翌日|よくじつ]のゼミで[使|つか]う[古|ふる]いカメラを、[茶色|ちゃいろ]い[革|かわ]のケースに[入|い]れたまま[教室|きょうしつ]の[机|つくえ]に[置|お]いた。そして、そこにいた[三人|さんにん]の[学生|がくせい]に「[大切|たいせつ]な[物|もの]だから、[触|さわ]らないように」と[伝|つた]えて[研究|けんきゅう][室|しつ]に[戻|もど]った。",
  "ところが、夕方五時に先生が教室に戻ると、ケースは机の上にあったが、中のカメラだけが消えていた。三人に聞くと、それぞれ午後四時ごろに別の用事で教室を離れたという。教室には鍵がかかっていなかったので、三人以外の誰かが入った可能性もないとは言えない。": "ところが、[夕方|ゆうがた][五時|ごじ]に[先生|せんせい]が[教室|きょうしつ]に[戻|もど]ると、ケースは[机|つくえ]の[上|うえ]にあったが、[中|なか]のカメラだけが[消|き]えていた。[三人|さんにん]に[聞|き]くと、それぞれ[午後|ごご][四時|よじ]ごろに[別|べつ]の[用事|ようじ]で[教室|きょうしつ]を[離|はな]れたという。[教室|きょうしつ]には[鍵|かぎ]がかかっていなかったので、[三人|さんにん][以外|いがい]の[誰|だれ]かが[入|はい]った[可能|かのう][性|せい]もないとは[言|い]えない。",
  "小林先生は一人ずつ話を聞いた。佐々木は「図書館でレポートを書いていました。ケースには一度も触っていません」と言った。原田は「食堂で友達とお茶を飲んでいました。それにしても、あんな黒くて小さいカメラ、誰が欲しがるんでしょうね」と首をかしげた。山口は「アルバイトの面接に行っていました。中にどんなカメラが入っていたのかも知りません」と答えた。": "[小林|こばやし][先生|せんせい]は[一人|ひとり]ずつ[話|はなし]を[聞|き]いた。[佐々木|ささき]は「[図書館|としょかん]でレポートを[書|か]いていました。ケースには[一度|いちど]も[触|さわ]っていません」と[言|い]った。[原田|はらだ]は「[食堂|しょくどう]で[友達|ともだち]とお[茶|ちゃ]を[飲|の]んでいました。それにしても、あんな[黒|くろ]くて[小|ちい]さいカメラ、[誰|だれ]が[欲|ほ]しがるんでしょうね」と[首|くび]をかしげた。[山口|やまぐち]は「アルバイトの[面接|めんせつ]に[行|い]っていました。[中|なか]にどんなカメラが[入|はい]っていたのかも[知|し]りません」と[答|こた]えた。",
  "三人の話を聞き終えると、小林先生は原田に向かって穏やかに言った。「原田君、あのカメラはずっと茶色い革のケースに入っていて、私は一度も中から出していない。君たちは誰も中身を見ていないはずだ。それなのに、どうして黒くて小さいカメラだと知っているのかな。」": "[三人|さんにん]の[話|はなし]を[聞|き]き[終|お]えると、[小林|こばやし][先生|せんせい]は[原田|はらだ]に[向|む]かって[穏|おだ]やかに[言|い]った。「[原田|はらだ][君|くん]、あのカメラはずっと[茶色|ちゃいろ]い[革|かわ]のケースに[入|はい]っていて、[私|わたし]は[一度|いちど]も[中|なか]から[出|だ]していない。[君|きみ]たちは[誰|だれ]も[中身|なかみ]を[見|み]ていないはずだ。それなのに、どうして[黒|くろ]くて[小|ちい]さいカメラだと[知|し]っているのかな。」",
  "原田はしばらく言葉に詰まっていたが、やがて正直に話し始めた。古いカメラに興味があり、少しだけ見るつもりでケースを開けたところ、うっかり落として傷をつけてしまった。怒られるのが怖くなり、自分のロッカーに隠したのだという。先生は笑って、「正直に言ってくれてよかった」と言った。": "[原田|はらだ]はしばらく[言葉|ことば]に[詰|つ]まっていたが、やがて[正直|しょうじき]に[話|はな]し[始|はじ]めた。[古|ふる]いカメラに[興味|きょうみ]があり、[少|すこ]しだけ[見|み]るつもりでケースを[開|あ]けたところ、うっかり[落|お]として[傷|きず]をつけてしまった。[怒|おこ]られるのが[怖|こわ]くなり、[自分|じぶん]のロッカーに[隠|かく]したのだという。[先生|せんせい]は[笑|わら]って、「[正直|しょうじき]に[言|い]ってくれてよかった」と[言|い]った。",
  "小林先生が教室に置いたとき、カメラはどんな状態だったか。": "[小林|こばやし][先生|せんせい]が[教室|きょうしつ]に[置|お]いたとき、カメラはどんな[状態|じょうたい]だったか。",
