  "新しい 証拠が 見つかった（　）、捜査は 一気に 進んだ。": "[新|あたら]しい [証拠|しょうこ]が [見|み]つかった（　）、[捜査|そうさ]は [一気|いっき]に [進|すす]んだ。",
