  "筆者が大切だと考えていることは何か。": "[筆者|ひっしゃ]が[大切|たいせつ]だと[考|かんが]えていることは[何|なに]か。",
  "人は、自分が信じたい情報ばかりを集めてしまう傾向がある。探偵が犯人を決めつけて捜査を進めると、その人物に有利な証拠を見逃してしまうことがある。大切なのは、自分の仮説が間違っている可能性を常に考えることだ。": "[人|ひと]は、[自分|じぶん]が[信|しん]じたい[情報|じょうほう]ばかりを[集|あつ]めてしまう[傾向|けいこう]がある。[探偵|たんてい]が[犯人|はんにん]を[決|き]めつけて[捜査|そうさ]を[進|すす]めると、その[人物|じんぶつ]に[有利|ゆうり]な[証拠|しょうこ]を[見逃|みのが]してしまうことがある。[大切|たいせつ]なのは、[自分|じぶん]の[仮説|かせつ]が[間違|まちが]っている[可能|かのう][性|せい]を[常|つね]に[考|かんが]えることだ。",
