  "犯人と 決めつけた 人物が 犯人では ない ことを 示す 証拠": "[犯人|はんにん]と [決|き]めつけた [人物|じんぶつ]が [犯人|はんにん]では ない ことを [示|しめ]す [証拠|しょうこ]",
