  "このメールで一番伝えたいことは何か。": "このメールで[一番|いちばん][伝|つた]えたいことは[何|なに]か。",
  "件名：打ち合わせ日程変更のお願い\nお世話になっております。来週十五日に予定しておりました打ち合わせですが、弊社の都合により、十七日以降に変更していただけないでしょうか。ご都合のよい日時を、今週中にお知らせいただけますと幸いです。": "[件名|けんめい]：[打ち合|うちあ]わせ[日程|にってい][変更|へんこう]のお[願|ねが]い\nお[世話|せわ]になっております。[来週|らいしゅう][十|じゅう][五日|いつか]に[予定|よてい]しておりました[打ち合|うちあ]わせですが、[弊社|へいしゃ]の[都合|つごう]により、[十|じゅう][七日|なのか][以降|いこう]に[変更|へんこう]していただけないでしょうか。ご[都合|つごう]のよい[日時|にちじ]を、[今週|こんしゅう][中|ちゅう]にお[知|し]らせいただけますと[幸|さいわ]いです。",
