  "今週中に 都合の いい 日時を 知らせる": "[今週|こんしゅう][中|ちゅう]に [都合|つごう]の いい [日時|にちじ]を [知|し]らせる",
  "十五日に 会社へ 行く": "[十|じゅう][五日|いつか]に [会社|かいしゃ]へ [行|い]く",
  "十七日に 必ず 会議を する": "[十|じゅう][七日|なのか]に [必|かなら]ず [会議|かいぎ]を する",
  "来週中に 返事を する": "[来週|らいしゅう][中|ちゅう]に [返事|へんじ]を する",
  "若者が紙の手帳を使う理由として本文に合うものはどれか。": "[若者|わかもの]が[紙|かみ]の[手帳|てちょう]を[使|つか]う[理由|りゆう]として[本文|ほんぶん]に[合|あ]うものはどれか。",
  "近年、紙の手帳を使う若者が再び増えているという。スマートフォンで予定を管理するほうが便利なはずだが、手で書くことで記憶に残りやすく、気持ちも整理できるのが理由だそうだ。便利さだけが選ばれる理由ではないということだろう。": "[近年|きんねん]、[紙|かみ]の[手帳|てちょう]を[使|つか]う[若者|わかもの]が[再|ふたた]び[増|ふ]えているという。スマートフォンで[予定|よてい]を[管理|かんり]するほうが[便利|べんり]なはずだが、[手|て]で[書|か]くことで[記憶|きおく]に[残|のこ]りやすく、[気持|きも]ちも[整理|せいり]できるのが[理由|りゆう]だそうだ。[便利|べんり]さだけが[選|えら]ばれる[理由|りゆう]ではないということだろう。",
