  "スマートフォンの ほうが 記憶に 残る": "スマートフォンの ほうが [記憶|きおく]に [残|のこ]る",
  "若者は 便利な ものしか 使わない": "[若者|わかもの]は [便利|べんり]な ものしか [使|つか]わない",
  "期間中、お弁当を買いたい人はどうしなければならないか。": "[期間|きかん][中|ちゅう]、お[弁当|べんとう]を[買|か]いたい[人|ひと]はどうしなければならないか。",
  "【社員食堂改装のお知らせ】\n改装工事のため、三月一日から三月二十日まで社員食堂を休業いたします。期間中は一階会議室にてお弁当を販売いたします。なお、お弁当は予約制となりますので、前日の午後三時までに総務課へお申し込みください。": "【[社員|しゃいん][食堂|しょくどう][改装|かいそう]のお[知|し]らせ】\n[改装|かいそう][工事|こうじ]のため、[三月|さんがつ][一|いち][日|にち]から[三月|さんがつ][二十日|はつか]まで[社員|しゃいん][食堂|しょくどう]を[休業|きゅうぎょう]いたします。[期間|きかん][中|ちゅう]は[一階|いっかい][会議|かいぎ][室|しつ]にてお[弁当|べんとう]を[販売|はんばい]いたします。なお、お[弁当|べんとう]は[予約|よやく][制|せい]となりますので、[前日|ぜんじつ]の[午後|ごご][三時|さんじ]までに[総務|そうむ][課|か]へお[申し込|もうしこ]みください。",
