  "本文によると、記憶が書き換えられる原因は何か。": "[本文|ほんぶん]によると、[記憶|きおく]が[書き換|かきか]えられる[原因|げんいん]は[何|なに]か。",
  "証言というものは、思っている以上にあいまいだ。人は見たものをそのまま覚えているのではなく、後から聞いた話や自分の思い込みによって、記憶を無意識に書き換えてしまう。目撃者が自信を持って話していても、それが正確だとは限らないのである。": "[証言|しょうげん]というものは、[思|おも]っている[以上|いじょう]にあいまいだ。[人|ひと]は[見|み]たものをそのまま[覚|おぼ]えているのではなく、[後|ご]から[聞|き]いた[話|はなし]や[自分|じぶん]の[思い込|おもいこ]みによって、[記憶|きおく]を[無意識|むいしき]に[書き換|かきか]えてしまう。[目撃|もくげき][者|しゃ]が[自信|じしん]を[持|も]って[話|はな]していても、それが[正確|せいかく]だとは[限|かぎ]らないのである。",
