  "内容は できて いるんですが、データの 確認が まだで…。": "[内容|ないよう]は できて いるんですが、データの [確認|かくにん]が まだで…。",
  "データは 田中さんが 詳しいから、確認を お願いしたら？": "データは [田中|たなか]さんが [詳|くわ]しいから、[確認|かくにん]を お[願|ねが]いしたら？",
  "田中さんに データの 確認を 頼む": "[田中|たなか]さんに データの [確認|かくにん]を [頼|たの]む",
