  "ええ。背の 高い 男で、黒い 帽子を かぶって いました。暗かったので 顔は よく 見えませんでしたが、右手に 大きな かばんを 持って いました。": "ええ。[背|せ]の [高|たか]い [男|おとこ]で、[黒|くろ]い [帽子|ぼうし]を かぶって いました。[暗|くら]かったので [顔|かお]は よく [見|み]えませんでしたが、[右手|みぎて]に [大|おお]きな かばんを [持|も]って いました。",
  "黒い 帽子を かぶった 背の 高い 男": "[黒|くろ]い [帽子|ぼうし]を かぶった [背|せ]の [高|たか]い [男|おとこ]",
