  "男の人は どうして 転職する ことに しましたか。": "[男|おとこ]の[人|ひと]は どうして [転職|てんしょく]する ことに しましたか。",
  "転職するんだって？ 給料に 不満でも あったの？": "[転職|てんしょく]するんだって？ [給料|きゅうりょう]に [不満|ふまん]でも あったの？",
  "いや、給料は 悪くなかったんだ。ただ、もっと 海外と 関わる 仕事が したくてね。": "いや、[給料|きゅうりょう]は [悪|わる]くなかったんだ。ただ、もっと [海外|かいがい]と [関|かか]わる [仕事|しごと]が したくてね。",
