  "失敗を 恐れて 何も しないのが、一番の 失敗です。うまく いかなかった ときは、その 原因を 考えれば、次に つながります。大切なのは、まず 挑戦して みる ことなのです。": "[失敗|しっぱい]を [恐|おそ]れて [何|なに]も しないのが、[一番|いちばん]の [失敗|しっぱい]です。うまく いかなかった ときは、その [原因|げんいん]を [考|かんが]えれば、[次|つぎ]に つながります。[大切|たいせつ]なのは、まず [挑戦|ちょうせん]して みる ことなのです。",
  "失敗を 恐れずに 挑戦する ことが 大切だ": "[失敗|しっぱい]を [恐|おそ]れずに [挑戦|ちょうせん]する ことが [大切|たいせつ]だ",
