  "調べたら、台風の 場合は 無料で 一週間後に 変更できるって。": "[調|しら]べたら、[台風|たいふう]の [場合|ばあい]は [無料|むりょう]で [一週間|いっしゅうかん][後|ご]に [変更|へんこう]できるって。",
