  "いや、彼は「雨が ひどくて、ずっと 家に いた」と 言った。だが、あの 日、雨が 降り始めたのは 夜中の 十二時過ぎだ。事件は 十時に 起きて いる。": "いや、[彼|かれ]は「[雨|あめ]が ひどくて、ずっと [家|いえ]に いた」と [言|い]った。だが、あの [日|にち]、[雨|あめ]が [降|お]り[始|はじ]めたのは [夜中|やちゅう]の [十二時|じゅうにじ][過|す]ぎだ。[事件|じけん]は [十時|じゅうじ]に [起|お]きて いる。",
  "事件の 時刻には まだ 雨が 降って いなかったから": "[事件|じけん]の [時刻|じこく]には まだ [雨|あめ]が [降|ふ]って いなかったから",
