  "うん。運動は 好きなんだけど、仕事が 遅く なる 日が 多くて、なかなか 行けなかったの。それなら お金が もったいないと 思って。": "うん。[運動|うんどう]は [好|す]きなんだけど、[仕事|しごと]が [遅|おそ]く なる [日|ひ]が [多|おお]くて、なかなか [行|い]けなかったの。それなら お[金|かね]が もったいないと [思|おも]って。",
