  "窓は雪がやむ前に割られたこと": "[窓|まど]は[雪|ゆき]がやむ[前|まえ]に[割|わ]られたこと",
  "犯人は誰か。また、その決め手となったのは何か。": "[犯人|はんにん]は[誰|だれ]か。また、その[決め手|きめて]となったのは[何|なに]か。",
  "田所。破片の上に雪がなく、一時に音を聞いたという証言と矛盾したから": "[田所|たどころ]。[破片|はへん]の[上|うえ]に[雪|そそ]がなく、[一時|いちじ]に[音|おと]を[聞|き]いたという[証言|しょうげん]と[矛盾|むじゅん]したから",
