  "桐生が真相に気づく決め手となった手がかりはどれか。": "[桐生|きりゅう]が[真相|しんそう]に[気|き]づく[決め手|きめて]となった[手|て]がかりはどれか。",
  "傘立てには学生の傘一本しかなく、灰色のコートの男は手ぶらなのに肩が濡れていたこと": "[傘|かさ][立|だ]てには[学生|がくせい]の[傘|かさ][一本|いっぽん]しかなく、[灰色|はいいろ]のコートの[男|おとこ]は[手|て]ぶらなのに[肩|かた]が[濡|ぬ]れていたこと",
  "学生が文学の棚の前に長い時間立っていたこと": "[学生|がくせい]が[文学|ぶんがく]の[棚|たな]の[前|まえ]に[長|なが]い[時間|じかん][立|た]っていたこと",
  "婦人が数分で詩集を一冊買っていったこと": "[婦人|ふじん]が[数|すう][分|ふん]で[詩集|ししゅう]を[一|いち][冊|さつ][買|か]っていったこと",
