  "近所の大学に通う学生": "[近所|きんじょ]の[大学|だいがく]に[通|かよ]う[学生|がくせい]",
  "和服姿の年配の婦人": "[和服|わふく][姿|すがた]の[年配|ねんぱい]の[婦人|ふじん]",
  "孫娘の沙織": "[孫娘|まごむすめ]の[沙織|さおり]",
  "打ち上げられなかった花火": "[打ち上|うちあ]げられなかった[花火|はなび]",
  "海沿いの町にある小さな美術館で、収蔵庫に保管されていた江戸期の掛け軸が盗まれたのは、八月十日の夜のことであった。翌朝、出勤した職員が収蔵庫の扉の錠が開いているのを発見し、警察に通報した。収蔵庫の鍵を扱えるのは、館長を除けば三人しかいない。県警の刑事である真柴は、その三人から事件当夜の行動を聞くことにした。": "[海沿|うみぞ]いの[町|まち]にある[小|ちい]さな[美術館|びじゅつかん]で、[収蔵|しゅうぞう][庫|こ]に[保管|ほかん]されていた[江戸|えど][期|き]の[掛け軸|かけじく]が[盗|ぬす]まれたのは、[八月|はちがつ][十日|とおか]の[夜|よる]のことであった。[翌朝|よくあさ]、[出勤|しゅっきん]した[職員|しょくいん]が[収蔵|しゅうぞう][庫|こ]の[扉|とびら]の[錠|じょう]が[開|ひら]いているのを[発見|はっけん]し、[警察|けいさつ]に[通報|つうほう]した。[収蔵|しゅうぞう][庫|こ]の[鍵|かぎ]を[扱|あつか]えるのは、[館長|かんちょう]を[除|のぞ]けば[三人|さんにん]しかいない。[県警|けんけい]の[刑事|けいじ]である[真柴|ましば]は、その[三人|さんにん]から[事件|じけん][当夜|とうや]の[行動|こうどう]を[聞|き]くことにした。",
  "一人目の警備員の大野は、その夜、館内で勤務していた。巡回の記録は一時間ごとに機械に残されており、どの時刻にも空白は見当たらない。二人目の学芸員の森下は、十日から二日間、遠方の都市で開かれた学会に出席しており、ホテルの宿泊記録や講演の録画がそれを裏付けていた。": "[一人|ひとり][目|め]の[警備|けいび][員|いん]の[大野|おおの]は、その[夜|よる]、[館内|かんない]で[勤務|きんむ]していた。[巡回|じゅんかい]の[記録|きろく]は[一時間|いちじかん]ごとに[機械|きかい]に[残|のこ]されており、どの[時刻|じこく]にも[空白|くうはく]は[見当|みあ]たらない。[二人|ふたり][目|め]の[学芸|がくげい][員|いん]の[森下|もりした]は、[十日|とおか]から[二日間|ふつかかん]、[遠方|えんぽう]の[都市|とし]で[開|ひら]かれた[学会|がっかい]に[出席|しゅっせき]しており、ホテルの[宿泊|しゅくはく][記録|きろく]や[講演|こうえん]の[録画|ろくが]がそれを[裏付|うらづ]けていた。",
  "三人目は、修復を担当する外部の技術者、篠田である。篠田は少し照れたような笑みを浮かべて言った。「あの晩は、河原で花火を見ていました。毎年の楽しみなんですよ。九時ごろから一時間ほど、最後の金色の大輪まで見届けて帰りました。あいにく携帯の電池が切れていて、写真は一枚も残っていませんが」。花火の様子を語る篠田の口ぶりは淀みなく、その光景が目に浮かぶようであった。真柴は黙って手帳に書き留めながら、どこか引っかかるものを感じていた。": "[三人|さんにん][目|め]は、[修復|しゅうふく]を[担当|たんとう]する[外部|がいぶ]の[技術|ぎじゅつ][者|しゃ]、[篠田|しのだ]である。[篠田|しのだ]は[少|すこ]し[照|て]れたような[笑|え]みを[浮|う]かべて[言|い]った。「あの[晩|ばん]は、[河原|かわら]で[花火|はなび]を[見|み]ていました。[毎年|まいとし]の[楽|たの]しみなんですよ。[九時|くじ]ごろから[一時間|いちじかん]ほど、[最後|さいご]の[金色|きんいろ]の[大輪|たいりん]まで[見届|みとど]けて[帰|かえ]りました。あいにく[携帯|けいたい]の[電池|でんち]が[切|き]れていて、[写真|しゃしん]は[一|いち][枚|まい]も[残|のこ]っていませんが」。[花火|はなび]の[様子|ようす]を[語|かた]る[篠田|しのだ]の[口|くち]ぶりは[淀|よど]みなく、その[光景|こうけい]が[目|め]に[浮|う]かぶようであった。[真柴|ましば]は[黙|だま]って[手帳|てちょう]に[書き留|かきと]めながら、どこか[引|ひ]っかかるものを[感|かん]じていた。",
  "真柴は礼を述べて篠田と別れると、その足で町の観光協会に向かった。窓口の職員は、壁に貼られたポスターを指さして言った。「今年の花火大会ですか。本来は十日の予定でしたが、あの日は台風の影響で夕方から風が強まりましてね。安全のため、翌日の十一日に延期したんです」。真柴が念のために確かめると、十日の夜は河原に人影もなく、花火の音を聞いたという住民も一人もいなかった。": "[真柴|ましば]は[礼|れい]を[述|の]べて[篠田|しのだ]と[別|わか]れると、その[足|あし]で[町|まち]の[観光|かんこう][協会|きょうかい]に[向|む]かった。[窓口|まどぐち]の[職員|しょくいん]は、[壁|かべ]に[貼|は]られたポスターを[指|ゆび]さして[言|い]った。「[今年|ことし]の[花火|はなび][大会|たいかい]ですか。[本来|ほんらい]は[十日|とおか]の[予定|よてい]でしたが、あの[日|ひ]は[台風|たいふう]の[影響|えいきょう]で[夕方|ゆうがた]から[風|かぜ]が[強|つよ]まりましてね。[安全|あんぜん]のため、[翌日|よくじつ]の[十|じゅう][一|いち][日|にち]に[延期|えんき]したんです」。[真柴|ましば]が[念|ねん]のために[確|たし]かめると、[十日|とおか]の[夜|よる]は[河原|かわら]に[人影|ひとかげ]もなく、[花火|はなび]の[音|おと]を[聞|き]いたという[住民|じゅうみん]も[一人|ひとり]もいなかった。",
  "真柴の頭の中で、すべてがつながった。篠田が見たという花火は、十日の夜には一発も打ち上げられていなかったのである。彼はおそらく、翌日の花火大会を実際に見て、その記憶をもとに偽りのアリバイを組み立てたのだろう。警備員の記録にも、学芸員の出張にも、ほころびは見当たらない。巧みに作られた嘘ほど、思わぬ一つの事実によって、あっけなく崩れ去るものである。": "[真柴|ましば]の[頭|あたま]の[中|なか]で、すべてがつながった。[篠田|しのだ]が[見|み]たという[花火|はなび]は、[十日|とおか]の[夜|よる]には[一|いち][発|はつ]も[打ち上|うちあ]げられていなかったのである。[彼|かれ]はおそらく、[翌日|よくじつ]の[花火|はなび][大会|たいかい]を[実際|じっさい]に[見|み]て、その[記憶|きおく]をもとに[偽|いつわ]りのアリバイを[組み立|くみた]てたのだろう。[警備|けいび][員|いん]の[記録|きろく]にも、[学芸|がくげい][員|いん]の[出張|しゅっちょう]にも、ほころびは[見当|みあ]たらない。[巧|たく]みに[作|つく]られた[嘘|うそ]ほど、[思|おも]わぬ[一|ひと]つの[事実|じじつ]によって、あっけなく[崩|くず]れ[去|さ]るものである。",
  "学芸員の森下の行動を裏付けたものは何か。": "[学芸|がくげい][員|いん]の[森下|もりした]の[行動|こうどう]を[裏付|うらづ]けたものは[何|なに]か。",
