  "筆者によると、推理小説の魅力はどこにあるか。": "[筆者|ひっしゃ]によると、[推理|すいり][小説|しょうせつ]の[魅力|みりょく]はどこにあるか。",
  "推理小説の魅力は、謎が解けた瞬間の快感だけにあるのではない。読者は探偵とともに手がかりを拾い集め、仮説を立てては崩していく。その過程こそが、読書を能動的な営みへと変えるのである。結末を先に知ってしまえば、この知的な楽しみは半減するだろう。": "[推理|すいり][小説|しょうせつ]の[魅力|みりょく]は、[謎|なぞ]が[解|と]けた[瞬間|しゅんかん]の[快感|かいかん]だけにあるのではない。[読者|どくしゃ]は[探偵|たんてい]とともに[手|て]がかりを[拾|ひろ]い[集|あつ]め、[仮説|かせつ]を[立|た]てては[崩|くず]していく。その[過程|かてい]こそが、[読書|どくしょ]を[能動|のうどう][的|てき]な[営|いとな]みへと[変|か]えるのである。[結末|けつまつ]を[先|さき]に[知|し]ってしまえば、この[知的|ちてき]な[楽|たの]しみは[半減|はんげん]するだろう。",
