  "筆者は「疑うこと」をどのように考えているか。": "[筆者|ひっしゃ]は「[疑|うたが]うこと」をどのように[考|かんが]えているか。",
  "情報があふれる現代において、真偽を見極める力はかつてないほど重要になっている。発信者の意図や根拠の有無を確かめず、刺激的な見出しだけで判断すれば、誤った情報の拡散に加担しかねない。疑うことは、相手を信用しないことではなく、自分の判断に責任を持つことなのだ。": "[情報|じょうほう]があふれる[現代|げんだい]において、[真偽|しんぎ]を[見極|みきわ]める[力|ちから]はかつてないほど[重要|じゅうよう]になっている。[発信|はっしん][者|しゃ]の[意図|いと]や[根拠|こんきょ]の[有無|うむ]を[確|たし]かめず、[刺激|しげき][的|てき]な[見出|みだ]しだけで[判断|はんだん]すれば、[誤|あやま]った[情報|じょうほう]の[拡散|かくさん]に[加担|かたん]しかねない。[疑|うたが]うことは、[相手|あいて]を[信用|しんよう]しないことではなく、[自分|じぶん]の[判断|はんだん]に[責任|せきにん]を[持|も]つことなのだ。",
