  "冤罪がなくならない背景として挙げられているものはどれか。": "[冤罪|えんざい]がなくならない[背景|はいけい]として[挙|あ]げられているものはどれか。",
  "冤罪がなくならない背景には、自白を重視しすぎる捜査の在り方があると指摘されている。長時間の取り調べで心身ともに追い詰められた人は、やってもいない罪を認めてしまうことがある。客観的な証拠に基づく捜査の徹底が、何よりも求められている。": "[冤罪|えんざい]がなくならない[背景|はいけい]には、[自白|じはく]を[重視|じゅうし]しすぎる[捜査|そうさ]の[在り方|ありかた]があると[指摘|してき]されている。[長時間|ちょうじかん]の[取り調|とりしら]べで[心身|しんしん]ともに[追い詰|おいつ]められた[人|ひと]は、やってもいない[罪|つみ]を[認|みと]めてしまうことがある。[客観|きゃっかん][的|てき]な[証拠|しょうこ]に[基|もと]づく[捜査|そうさ]の[徹底|てってい]が、[何|なに]よりも[求|もと]められている。",
