  "【重要】システムメンテナンスに伴うサービス停止について\n平素より当サービスをご利用いただき、誠にありがとうございます。十一月五日（水）午前二時から午前六時まで、システムメンテナンスを実施いたします。作業中は全サービスをご利用いただけません。なお、作業の進捗によっては、終了時刻が前後する場合がございます。": "【[重要|じゅうよう]】システムメンテナンスに[伴|ともな]うサービス[停止|ていし]について\n[平素|へいそ]より[当|とう]サービスをご[利用|りよう]いただき、[誠|まこと]にありがとうございます。[十一月|じゅういちがつ][五日|いつか]（[水|みず]）[午前|ごぜん][二時|にじ]から[午前|ごぜん][六時|ろくじ]まで、システムメンテナンスを[実施|じっし]いたします。[作業|さぎょう][中|ちゅう]は[全|ぜん]サービスをご[利用|りよう]いただけません。なお、[作業|さぎょう]の[進捗|しんちょく]によっては、[終了|しゅうりょう][時刻|じこく]が[前後|ぜんご]する[場合|ばあい]がございます。",
